// Generated by ios/scripts/export_summaries.sh from ios/Imtahan/Store/SubjectSummaries*.swift. Do not edit by hand.
const summariesData = {"Grafik Üretim Teknikleri":{"intro":{"heading":"Əsas açar: boya kalıbın harasındadır?","points":["**Yüksek baskı**: basan yer qabarıqdır, möhür kimi. Ağaç, linol, **tipo**, flekso.","**Çukur baskı**: boya oyuqlara dolur. Metal oyma, aquatinta, **tifdruk = gravür**.","**Düz baskı**: səth düzdür, su ilə yağ bir-birini itələyir. Taşbaskı, **ofset**.","**Elek baskı**: boya ələkdən keçir. **Serigrafi**."]},"quick":["Sümer → yazı · Çin → kâğıt · 1729 → Müteferrika · Vankulu → ilk kitab","Goya → aquatinta · Dürer → Almaniya · Hayter → Atölye 17 · Siegen → mezotinta","Linol → 1890 İngiltərə · Bewick → enine ağaç · Aslıer → Özgün Baskıresim","Serigrafi: emülsiyonu çamaşır suyu təmizləyir, qaranlıq otaq","Tipo: anterlin, mürettip, pilyaj, gofre","Ofset: kalıp kâğıza toxunmur · tiksotropi · violet kalıp","Tifdruk: krom kaplama, elmas uc · Flekso: aniloks 60°","Esnek ambalaj: fotosel beneği 5×15 mm · şişirme 0,15–0,2 mm · barkod 13 rəqəm · InDesign\/Corel yox","Dijital: kalıpsız, değişken veri · toner → sürətli, bahalı · inkjet → ucuz · CLP → bobin beslemeli büyük format","Xerox PARC → başlanğıc · 1982 Adobe → PostScript · Recto sağ, Verso sol · Alley, Bleed, Glyph","Kâğıt: Ts'ai Lun, 105, Çin · kuşe → kaolin, tebeşir, kazein · 500 top, 250 paket · otokopi → mikro kapsül","RGB → beyaz · CMY → siyah · macenta ↔ yeşil · Pantone 18 mürekkep · düz yataklı → 200 mm · Plateau 1832 → Phenakistoscope"],"units":[{"blocks":[{"points":["Yazı: **Sümerlər** (ən böyük töhfələri). Kâğıt: **Çin**.","Ən erkən qrafik əsər: **Altamira** mağarası, əl kalıb kimi."]},{"heading":"Osmanlı","points":["İlk matbaa: **1493**.","İlk **rəsmi Türk** matbaası: **1729, İstanbul**, İbrahim Müteferrika.","Lale Devri, ilk Türkcə kitab: **Vankulu Lügatı**.","Müteferrikanın xəritəsi: **Karadeniz Haritası**.","**Cihannüma**: çizim və xəritə baxımından zəngin.","Taşbaskı ustası: **Mehmet Hulusi** (II. Abdülhamit dövrü)."]}],"number":1,"title":"Tarix","traps":["\"Gutenberg ilk kâğıt baskı makinasını yaptı\" inkişaflardan biri **deyil**.","Matbaa ilə \"monarşinin güclənməsi\" arasında əlaqə **yoxdur**.","Cihannüma Müteferrikanın ikinci dövrünün kitabı **deyil**.","Tarih-i Hind-i Garbi ilk taş basma atölyesində basılmayıb."]},{"blocks":[{"points":["Prinsip: basılacak alanlar **yüksəkdir**. Anadoluda ən erkən görülən texnika.","Növləri: **ağaç baskı, linol**. Linolyum kalıbı → yüksek baskı.","**Linol**: 1890, İngiltərə, Waltan Als Baden Belag. Sənət məktəblərində ən çox seçilən.","Ağaç kalıbı **lifli**dir. Kalıb hazırlamada **2** üsul, mürəkkəb **2** növ.","Boya verən kauçuklu silindr: **merdane**."]},{"heading":"Adlar","points":["**Diamond Sutra** (869, Çin, Wang Chieh): ağaç baskı.","**Gutenberg**: matbaanın qurucusu, modern baskının öncüsü.","**Ugo da Carpi** (1516, İtaliya): tahta kalıbla rəngli baskı.","**Thomas Bewick**: enine kəsilmiş sərt ağaç (şimşir, gürgen).","**Mustafa Aslıer**: \"Özgün Baskıresim\" terminini ilk işlədən."]}],"number":2,"title":"Yüksek baskı","traps":["**İpək kalıb** və **rakle** yüksek baskıya aid deyil (serigrafi).","**Şeker Ahmet Paşa** yüksek baskı sənətçisi deyil.","Gravür çukur baskıdır."]},{"blocks":[{"points":["İlk baskı: **Sümerlər**, kil üzərində silindir möhür.","Metal üzərinə ilk çukur baskı: **15. əsr**.","Türkiyədə ilk dərs: **Sanayi-i Nefise Mektebi**."]},{"heading":"Adlar","points":["**Dürer**: Almaniya, metal oyma.","**Goya**: aquatintanı ilk işlədən, \"Caprichos\".","**Ludwig von Siegen**: mezotinta (beşik formalı alət).","**Hayter**: Atölye 17.  **Süleyman Saim Tekcan**: İMOGA."]},{"heading":"Kuru kazı vs asitli oyma","points":["Kuru kazı turşusuzdur: burin ilə oyma, **kalburlama** (biz\/mismara çəkiclə vurmaq).","Asitli oyma: lövhə laklanır, çizilir, **asit küvetinə** qoyulur. Yumuşak vernik, aquatinta bu qrupdadır.","Tül, tük, yarpaq, ip, parça, zımpara: **doku aktararak** çukur baskı."]}],"number":3,"title":"Çukur baskı","traps":["\"Ahşap kimi maddələrdən yararlanılır\" çukur baskının tərifində **yoxdur**.","\"Çukur baskı elle basılır\" tərifin xüsusiyyəti **deyil**.","Aquatinta və yumuşak vernik kuru kazı **deyil**.","Kalburlama asitli oyma **deyil**."]},{"blocks":[{"points":["Digər adı: **elek baskı**. Material: **emülsiyon**.","Emülsiyon çəkiləndə otaq **qaranlıq**, birbaşa işıq almamalıdır.","Emülsiyonu elekdən **çamaşır suyu** təmizləyir.","Su bazlı boya → **su**. Selülozik boya → **selülozik tiner**.","Sektor: **seramik** sanayii. Maşın: **silindirik səth** baskı maşını.","Kurutma elementi: **kurutma rafı**.","Rakle: tekstil üçün **yuvarlaq uçlu**."]}],"number":4,"title":"Serigrafi (elek baskı)","traps":["**Pad baskı** serigrafinin adı deyil.","**Pamuk** dokuma\/gaze deyil. **Metal gaze** kimyəvi maddə deyil.","**Pres** serigrafi aləti deyil. **Geri dönüşüm** sektor deyil.","\"İçə kavisli\" rakle profili yoxdur. \"Çevirmeli\" maşın yoxdur.","Kalıbdakı artıq mürəkkəbi **emülsiyon temizleyici** ilə silmirlər."]},{"blocks":[{"points":["**Gutenberg**, 1440-lar. Basan yer hündürdür.","**Hurufat** basan materialdır. **Anterlin**: basmayan, sətir arasını açır.","**Mürettip**: kasadan kumpasa dizgi edən.","**El pedalı**: kartvizit, davetiye, zəif pres. **Rotatif tipo**: sürətli, silindirik.","**Pilyaj**: katlama izi. **Gofre**: kabartma.","Ofset tiponu əvəz etdi, çünki **yağ bazlı mürəkkəb**.","Tipo ilə trigromi edilmir, çünki baskı **keyfiyyətsizdir**."]}],"number":5,"title":"Tipo baskı","traps":["Kurşun kalıp tiponun **üstünlüyü deyil**.","Keski ilə **kitab** basılmaz.","Sıcak yaldız **gazetdə** istifadə olunmur. \"Sıcak yaldız\" yaldız çeşidi kimi səhv variantdır.","\"Ara ton içermeyen klişelere oto tipi denir\" **yanlışdır**.","Keski kalıbında yalnız kəsim bıçağı **olmur**."]},{"blocks":[{"points":["Kalıp kâğıza **toxunmur**, rəsm kauçuk üzərindən keçir.","**Poza tertibatı**: kâğızı yana çəkir. **Vargel merdanesi**: suyu nəmləndirmə merdanesinə verir.","**Havalı kauçuk**: çiftləmə və kayma az olur.","**Violet kalıp**: gün işığı, gümüş halojenür, CtP. **Anodlama**: kalıbı möhkəmləndirir."]},{"heading":"Mürəkkəb","points":["**Tiksotropi**: durğunda bərk, qarışdıranda axır.","Işıq haslığını **pigment** təyin edir.","UV\/IR ilə: **radyasyon kuruma**. Kâğızın hopdurması: **nüfuz ederek kuruma**.","Su azalanda, mürəkkəb çox olanda: **tramlar dolar**, boş yerlərdə ton yaranır.","**Fırçalı nəmləndirmə**: hazne suyu kirlənmir."]}],"number":6,"title":"Ofset","traps":["Tabaka ofsetdə **bobin standı** yoxdur. Web ofsetdə **kâğıt istif asansörü** yoxdur.","Kalıp nemlendirme merdanesi mürəkkəb ünitəsinə aid deyil.","\"Az su ilə su xərcini azaltmaq\" hazne suyu katkısının məqsədi **deyil**.","\"Az su ilə maliyyət düşür\" CtP-nin üstünlüyü **deyil**."]},{"blocks":[{"heading":"Tifdruk (gravür)","points":["Türkcəsi **çukur baskı**. 15. əsr, Almaniya, esnek ambalaj.","Əsas üstünlük: **uzun metraj**.","Silindir 3 üsulla: **İnce Tabaka – Ballardskin – Ağır Bakır**.","Kazıma **elmas** uclu, sonra **krom** kaplama.","Maşın enləri: **110–120–140–160 sm**. **Prova maşını** yükü azaldır."]},{"heading":"Flekso","points":["**Aniloks merdane**: mürəkkəb qalınlığını ayarlayır, deseni **60°**.","**Solvent** sürətli kurudur. Alkol bazlı viskozite: **14\"–18\"**.","Klişe pozlama: **sırt → negatif → ön → yıkama → son poz**."]}],"number":7,"title":"Tifdruk və flekso","traps":["**Çelik kaplama** silindir aşaması deyil.","**Dijital baskı** esnek ambalaj texnikası deyil.","\"Plastik boya\" flekso mürəkkəbinin xüsusiyyəti deyil.","Silindir hazırlığında \"elmas keyfiyyəti\" nəzərə alınmır."]},{"blocks":[{"points":["**Esnek ambalaj** = **tifdruk** (rotogravür) və **flekso** baskı ürünləri. Matbaacılığın 3 texnikası: ofset, flekso, tifdruk.","Inline **10 rəngə** qədər; bura **Beyaz, Matlak, Release Lak, Primer Lak, Cold Seal, Holtmelt** də daxildir.","Proqram: **Illustrator**, Photoshop, Acrobat Pro, **Artpro \/ Artpro+ \/ Hybrid Packs** (repro, silindir\/klişe montajı), GMG.","Renk yönetimi: hər firma **GMG Open Color** ilə öz **CMYK profilini** yaradır."]},{"heading":"Ölçü və işarələr","points":["Əvvəlcə **bobin eni** (en) və **fotosel boyu** (boy) bilinməlidir. **Yaka**: paketləmə maşınına taxılan aparat.","**Fotosel beneği** məcburidir: **kontrast** rəngdə, kanalı boş, adətən **5×15 mm**. Beneksiz → **sonsuz ambalaj** (yalnız bobin eni lazım).","**Cold Seal** gıdaya toxunmamalı → **parsiyel**; ayrıca silindir, yəni **+1 rəng**.","**Holtmelt**: şəkər, saqqız; həmişə **altda** qalan sahə, plan hər maşına xasdır.","Barkod: Türkiyə **13 rəqəm** (EAN13\/EAN8). İlk 3 → **ölkə kodu**, son → **kontrol**. **UPC-A** 12 rəqəm, ABŞ."]},{"heading":"Ambalaj biçimləri","points":["**Stand-up** (oturan), **Pillow pack** A\/B və A\/A, **Follow pack** (PCS ola bilər).","**Okuturya** = zarf tipi: yalnız sıcak yapışma. **Pouch**: toz\/granül (çorba, kahve). **Doypack**: hazır, kilitli poşet."]},{"heading":"Baskı öncəsi","points":["**Şişirme (trap)**: baskı **ayar kayıklığının** qarşısını alır, **0,15–0,2 mm**. Ofsetdən ən böyük fərq budur.","Min. **3,5 punto** yazı, **0,2 mm** xətt, min. nöqtə **%3**. Şəkil **CMYK, 300 dpi, .psd**; **.jpeg\/.png olmaz**.","Yazılar **convert** edilir (fontsuz vektor). Makine planı ayrıca **layer**-də qalır.","Yoxlama: **Window → Separations Preview → Overprint Preview** (renk ayrım, şişirme, overprint).","Yazı\/logo ölçüsü **Türk Gıda Kodeksi**nə görə (qramaj\/ml-ə uyğun). Özel renk → **Pantone kodu**.","**Parsiyel beyaz** boşluqları → **parlaq metalik** efekt."]}],"number":8,"title":"Esnek ambalaj tasarımı","traps":["**InDesign** və **Corel** esnek ambalajda işlədilmir.","Pillow pack A\/B və Okuturyada **soğuk yapışma (PCS) olmaz**.","Renkli çıkış Pantone-u **%100 göstərmir** (CMYK-da %85–90 zəmanət).","Ağ obyektlər (fincan, süt) **CMYK ilə basılmaz** — özel rəngə alınır.","Tasarım **ofset mantığı** ilə hazırlanmaz."]},{"blocks":[{"points":["Üstünlük: **kalıp və renk ayrımı yoxdur** → vaxt və maliyyət qənaəti; anlıq müdaxilə, **değişken veri baskısı**.","**Ofis tipi masaüstü**: **A4\/A3**, az adet (24–64 səhifəlik rapor). 2 növ: **tonerli (elektrofotografik)** və **inkjet**."]},{"heading":"Toner vs inkjet","points":["**Toner** (lazer): kuru\/ıslak, ofisdəkilər **kuru**. Daha **sürətli, keyfiyyətli**, **harmanlı** (arxalı-önlü), amma birim maliyyəti **yüksək**.","**Inkjet**: birim maliyyəti aşağı, **sonsuz tank**; transfer kâğıdı + ısı pres, promosyon üçün UV\/su bazlı."]},{"heading":"Profesyonel format","points":["Bölgü boya növünə yox, **baskı altı malzemesinin verilməsinə** görədir.","**Tabaka beslemeli**: toner + elektronik duyarlı mürəkkəb; fotokopiçilər, baskı mərkəzləri (kişiyə özəl yıllık, belge).","**Bobin beslemeli**: elektronik duyarlı **sıvı** mürəkkəb; qısa tirajlı **esnek ambalaj**, barkod\/güvenlik kodu, filmsiz-kalıpsız, az fire.","**Büyük format inkjet**: sıvı mürəkkəb, iç\/dış mekân, tabaka\/bobin, **su\/solvent** bazlı; tabelacı və açıkhava (keçə, kumaş, fuar).","İç mekân → **yüksək keyfiyyət**. Dış mekân → **dayanıqlıq, solmama**."]}],"number":9,"title":"Dijital baskı","traps":["Dijitalda kalıp **ümumiyyətlə yoxdur**: \"daha çox\/daha az baskı kalıbı\" üstünlük **deyil**.","\"Hepsi bir arada\" tarama\/faks və **bobinden bobine esnek ambalaj** büyük format özəlliyi **deyil**.","**Üç boyutlu objeye direkt baskı** bobin beslemeli özəlliyi deyil (düz yataklıdır)."]},{"blocks":[{"points":["Tanım: baskı və ya elektron yayın üçün kişisel **bilgisayar** işlətmək.","Grafik tasarım layihənin **hissəsinə**, masaüstü yayıncılık **bütün ürünə** fokuslanır; onu tasarımçı olmayan da edə bilər."]},{"heading":"Tarix","points":["**Xerox PARC** (Palo Alto): başlanğıc nöqtəsi; lazer yazıcı, Smalltalk, Ethernet, **WYSIWYG**.","**Steve Jobs**: ucuz kompüter, **Apple LaserWriter**, sayısal yazıtipləri.","**1982 Adobe Systems** → **PostScript**: cihazdan asılı olmayan sayfa tanımlama dili, 300 dpi."]},{"heading":"Ekran vs baskı","points":["**Elektronik sayfa**: basılmır. **Sanal sayfa**: hədəfi **baskı**, WYSIWYG ilə ekranda önizlənir.","Ekran → **RGB**, **PPI**. Baskı → **CMYK**, **DPI**. Sanal sayfa ölçüsü: kâğıt en-boy + **katlanma**.","**Mürekkep kapanı (ink trap)**: harf köşələri boşaldılır, mürəkkəb yayılmır. Ekranda **lazım deyil**."]},{"heading":"Proqram və terminlər","points":["**InDesign, QuarkXPress, Publisher, Scribus**, CorelDRAW.","**Recto** sağ (ön) səhifə, **Verso** sol. **Orphan** (yetim), **Widow** (dul).","**Alley**: sütun arası boşluq. **Bleed**: kəsim sərhədindən kənara daşan sahə. **Glyph**: karakter kodunu təmsil edən şəkil.","**Vektör**: riyazi əyrilər, **ölçək-bağımsız**. **Bitmap**: ızgaradakı nöqtələr."]}],"number":10,"title":"Masaüstü yayıncılık","traps":["**Visual Basic** masaüstü yayıncılıq yazılımı **deyil**.","Sanal sayfanın hədəfi ekran deyil, **baskıdır**.","PostScript-i **Apple deyil, Adobe** çıxarıb.","PPI baskı, DPI ekran ölçüsü **deyil** — tərsinədir."]},{"blocks":[{"points":["İlk kâğıt: **M.S. 105, Çin, Ts'ai Lun**. Papirüs: **Eski Mısırlılar**.","Əsas xammal **selüloz** (ağacdan); hamur **mekanik və kimyasal** üsulla. Xammal: çam, ladin, kavak; mısır, çeltik; paçavra, atık kâğıt.","Dövmə → liflər kabarır. **Dolgu, tutkal, boya** → düzgünlük, yoğunluk, dayanıqlıq. **Zamk** → su\/mürəkkəbə dayanıqlıq.","Qramaj: hamur miqdarı + **tel süzgecin** sürəti. Çox hamur + yavaş → qalın."]},{"heading":"Xüsusiyyətlər","points":["**Su yönü**: liflərin yönü; asan qatlanır, **düz yırtılır**.","**Gramaj** = 1 m² ağırlığı (240 g\/m²). 70×100 sm, 170 g → **119 g**.","**Yoğunluk**: baskının arxa üzə keçib-keçməməsi.","Tabaka: 57×82, 59,4×84, 64×90, 70×100. **500 = top**, **250 = paket**. Bobin → web ofset."]},{"heading":"Növlər","points":["**1. hamur**: paçavra + selüloz \/ saf selüloz, ağ. **2. hamur**: selüloz + ağac, sarımtıl. **3. hamur**: tam ağac hamuru, mekanik; bilet, kupon, **gazete**.","**Kuşe**: **kaolin, tebeşir, kazein**; mat, parlak, tek yüz, gofre (zenit). **Enzo**: kitab. **Pelur**: yarı şəffaf, 2.–3. nüsxə.","**Otokopi** (kendinden karbonlu): **mikro kapsül**; **verici → alıcı-verici → alıcı**. Çox forsa olmaz.","**Yırtılmayan**: **polietilen** lif, su keçirməz; emiciliyi **zəif**, boya yavaş qurur. Tekstil, yanğın cihazı etiketi.","**Ozalit**: montaj provası, amonyak buxarı. **Kromalüks**: bir üz parlaq, biri mat-grenli. **Çıkartma**: arxası yapışqanlı. **Fantezi**: bahalı, idxal."]}],"number":11,"title":"Kâğıt","traps":["Yırtılmayan kâğıdın emiciliyi **yüksək deyil**, mürəkkəb **yavaş** qurur.","Otokopi kâğıtlar fotokopi kâğıdı kimi **işlədilmir**.","**Atık plastik** kâğıt xammalı **deyil**.","Dolgu maddəsi \"düzgün katlanma\" **təmin etmir**.","\"Su yönünə düzgün yırtılmaz\" **yanlışdır**."]},{"blocks":[{"heading":"Nəzəriyyə","points":["**Newton**: prizma, güneş tayfı. **Thomas Young** 1802: üç koni. **Helmholtz** 1850: qısa (mavi), orta (yaşıl), uzun (qırmızı).","**Eklemeli** (ışık): **kırmızı, yeşil, koyu mavi** → **beyaz**. RGB, bütün ekranlar.","**Çıkarmalı** (pigment): **siyan, macenta, sarı** → **siyah**. CMYK, **K = siyah**.","**Gamut**: aygıtın üretə bildiyi **renk tayfı**."]},{"heading":"Qarışıqlar və zıtlıqlar","points":["Işık: kırmızı + yeşil = **sarı**, yeşil + koyu mavi = **siyan**, koyu mavi + kırmızı = **macenta**.","Pigment: macenta + sarı = **kırmızı**, sarı + siyan = **yeşil**, siyan + macenta = **koyu mavi**.","**Tamamlayıcı**: qarışıqda olmayan birincil. Macenta ↔ **yeşil**, siyan ↔ **kırmızı**, sarı ↔ koyu mavi. Ən güclü zıtlıq.","**Sıcak**: sarıdan mora qədər (macenta, sarı, turuncu). **Soğuk**: koyu mavidən yaşıla.","**Hue** = yalın hal, **Saturation** = saflıq, **Value** = açıq-koyu."]},{"heading":"Baskı və renk","points":["**Tire**: yarım ton yoxdur. **Tram (yarım ton)**: nöqtələr; hər rəngə **fərqli açı** → tramlama.","**Hexachrome**: CMYK + **turuncu, yeşil** → geniş gamut.","**Pantone**: **18 temel mürekkep**. Metalik və **floresan** (özü işıq saçır) CMYK ilə alınmır.","**Renk kontrol çubuğu**: kənarda, tutarlılıq ölçüsü. **Renk şişirme**: ağ xətlərin ayarı. **Kalıp**: metal, plastik, kauçuk."]}],"number":12,"title":"Renk","traps":["Eklemelidə **koyu mavi**, çıkarmalıda **siyan** — qarışdırma.","Macenta–sarı tamamlayıcı **deyil**; macentanın tamamlayıcısı **yeşil**dir.","CMYK ilə metalik, floresan, parlaq rəng **alınmır**.","CMYK-dakı **K** \"kırmızı\" **deyil**, siyahdır."]},{"blocks":[{"points":["Sektorun adı: **Açıkhava** (tabelacıdan böyük). Billboard, **CLP**, şehir mobilyaları, taşıt, fuar.","Ölçü, malzeme, üretim yöntemi və **etkileşim süresi** fərqlidir → tasarımçı montaja qədər hakim olmalıdır."]},{"heading":"Baskı","points":["**Bobin beslemeli büyük format**: trigromi + spot rəng, **tək parça** montaj, bobin eni **5 m**-ə qədər. CLP (**118×170**), billboard, **dorse çadırı**.","**Düz yataklı (flatbed)**: solmayan **UV + su bazlı** mürəkkəb, **200 mm**-ə qədər 3D obyektə birbaşa, kalıpsız, değişken veri (ahşap masa tablası)."]},{"heading":"Kəsim","points":["**CNC Router**: CAD sonrası **CAM** ilə; cephe kaplama, tabela, totem, fuar standı.","**Folyo kesim**: **plotter**; Türkiyədə ~**1990**-dan, əvvəl fırça ilə yazılırdı.","**Lazer**: metal-platin, mika-pleksi, kutu harf; **markalama** (kalem, rozet, çakmak) → promosyon."]},{"heading":"Kutu harf və taşıt","points":["**Kutu harf** = üç boyutlu yazı; bilgilendirme, yönlendirme, dekor.","Taşıt üzəri: kimə aid olduğu, logo, imaj. Tampon, ayna, kıvrım → **Cast folyo**."]}],"number":13,"title":"Dış mekân","traps":["**Cam** CNC Router malzemesi **deyil**.","**Gazete** dış mekân mecrası **deyil**.","**Etriye büküm kuşgözü delme** kutu harf donanımı **deyil**."]},{"blocks":[{"points":["Tanım: animasyon, illüstrasyon, tipografi, foto, müzik, video birləşimi; **çoklu disiplin**, əsası **zaman**.","Durağan, 2 boyutlu tasarımların **zaman bandında** hərəkətləndirilməsi."]},{"heading":"Tarix","points":["Mağarada **çox ayaqlı heyvan** → hərəkətli görüntü. Misir divarları, **Antik Yunan çömleği** (fırladıqca hərəkət).","**1832, Joseph Plateau** (Belçika) → **Phenakistoscope** (iki disk, ayna). **William George** → **Zoetrope** (aynasız).","Öz tarixi **20. əsr** əvvəlindən. Ən köhnə istifadə: kino\/TV **jenerikləri**."]},{"heading":"Ortam və unsurlar","points":["TV reklam, film, çizgi film, oyun, web, **interaktif**. **Çoklu ortam**: görüntü, metin, ses + **etkileşim**. **Yeni medya**: **mobil** (telefon, tablet).","Unsurlar: **görüntü, tipografi, zaman, değişim, ses, kurgu**. **Zaman** kilit nöqtədir, **ses** ən çox təsir edir.","Proqram: After Effects, Cinema 4D, Maya. **Anahtar kareler**: dəyişmənin örnək nöqtələri.","**Kamera** → **2,5 boyut** (2D obyektə dərinlik), perspektiv. **Aydınlatma** → inandırıcılıq, kölgə."]}],"number":14,"title":"Hareketli grafik","traps":["**Basılı yayınlar** hareketli grafik kullanım alanı **deyil**.","**Duygu** hareketli grafik unsuru **deyil**.","\"Yalnız TV və sinemaya xidmət edir\" tanım **ola bilməz**.","Zoetrope Plateau-nun deyil, **William George**-un icadıdır."]}]},"Özgün Baskı Teknikleri":{"intro":{"heading":"Əsas açar: kalıbın neçə növü var?","points":["**Yüksek baskı**: oyulmayan yer boya alır. Ağaç baskı, **ağaç gravür**, linol.","**Çukur baskı (Intaglio)**: metal plaka, boya çukurlarda qalır. Kuru kazıma, mezotint, **aquatinta**.","**Litografi (taş baskı)**: Senefelder, afişlər, sanatın demokratikləşməsi.","Tarix xətti: **Çin** (kâğıt, tahta baskı) → Gutenberg → Rönesans gravürü → 18-19. əsr akımları."]},"quick":["Kâğıt → Çin, Avropaya 12. əsr · Gutenberg → İncil · Scriptorium → manastır","Tək tərəf → Anopistografish · çift → Opisthografische · Ukiyo-e → Japonya","Senefelder → litografi · Rousseau → Barbizon · Lautrec → sarı-mavi-kırmızı","Edisyon → tümü · baskıcı baskısı → nümunə · tıpkıbasım → mexaniki","Intaglio → çukur · pahlama → 35-45° · mezotint → pürüzlendirme · noktalama → yuvarlaq oluk","Aquatinta → leke baskı, 30 sn-5 dk · creve · Urs Graf → 1513 · mumlama → 65 °C","Mantegna → ilk röprodüksiyon · Raimondi · Chiaroscuro → sert ışık-gölge · El Greco → Maniyerizm","Goya → akuatint, Kaprisler · Meryon → Paris · Turner → Romantizm","Monotip → en ilkel düz baskı, Castiglione · ofset → dengeleme transferi · dişi\/erkek kalıp → şablon","Kollagraf → kolaj+grafik · Nesch → metal grafik, 1925 · Margo → cellocut, 1931 · karborundum → silisyum karbür","Sumizuri-e → Beni-e\/Tan-e → Nishiki-e · Ukiyo-e → yüzen dünya, Chonin · Moronobu → ilk büyük usta","Duchamp → hazır nesne · Arp → rastlantısallık · Pop Art → 1950-lər, İngiltərə\/ABŞ · Sürrealistlər → Atelier 17","Müteferrika → Tarih-i Hind-i Garbî, 1730 · Kayol → Nuhbetü't-talim · Berger → ilk kadın gravürcü · Tekcan → IMOGA","Lorichs → 21 parça, 11 m · Kâtip Çelebi → Cihannüma · Vanmour → Kıyafet Albümü · Allom → 94 gravür","Ekslibris → Latınca, 15. yy Almanya · FISAE → 13x13 cm, X\/C\/L · Pektaş → 1997 AED · 2008 → İstanbul Ekslibris Müzesi"],"units":[{"blocks":[{"heading":"Mühür və yazı","points":["Mühür sınıfları: **damga, yüzük, silindir, silindir damga** (dördü də).","Silindir mühürdə **döndürme yöntemi** işlənir.","Səslər üçün işarələrlə söz yazan: **Fenike Alfabesi**.","Karolenj yazı sistemi: **Gotik**."]},{"heading":"Kâğıt və kitab","points":["Kâğıt ilk dəfə **Çin**də. Avropaya **12. əsr**də gəldi. Çindən Avropaya yayıldı.","Kitabın tarixi **kâğıt**ın tapılması ilə başlayır.","Çində çıxan kitab biçimi: **ağaç**.","Tahta baskının ən qədim nümunələri: **Çin**.","Avropada kitab çoğaltma: **4.-5. əsr**. Manastır atölyesi: **Scriptorium**."]},{"heading":"Baskı terminləri","points":["Yazı və rəsm eyni ağaca oyulur: **Blok baskı**.","Tək tərəfli baskı: **Anopistografish**. Çift tərəfli: **Opisthografische**.","Rəsmləri keyfiyyətli basan ilk metal: **bakır**.","Matbaanı icad edən: **Johannes Gutenberg**. İlk kitabı: **İncil**."]},{"heading":"Japonya","points":["**Ukiyo-e**: Japon kavramı.","**Tosusai Sharaku**: aktör portreleri."]}],"number":1,"title":"Baskının tarixi","traps":["Hareketli tip baskının xüsusiyyəti **deyil**: \"mürekkebi eşit yoğunlukta almaması\"."]},{"blocks":[{"points":["Baskıresim bir **sanat biçimidir**. Ən önəmli xüsusiyyəti: **çoğaltılabilir olması**.","İlk dəfə **kumaşa** basılıb. Ən önəmli buluş: **kâğıt**.","\"Çukur baskı **hangi yüzyılda bulunmuştur**?\" → **16. əsr**. Amma \"metal üzerine **ilk** çukur baskı\" → **15. əsr**. Sualın sözünə bax.","Romantizmdən əvvəl cəmiyyəti dəyişən düşüncə: **Rönesans**.","20. əsrdə baskıresim sənətçiləri **deneysel** işlərə yönəltdi."]},{"heading":"Adlar","points":["Litografini tapan: **Alois Senefelder**.","**Barbizon Okulu**: qurucusu **Theodore Rousseau**, manzara ressamlığını önəmli etdi.","\"Kaya Meşeleri\": **Theodore Rousseau**.","**Aubrey Beardsley**: Art Nouveau. Art Nouveau: **organik və eğrisel** formlar.","**Toulouse Lautrec**: afişdə **sarı-mavi-kırmızı**. \"Divan Japonnais\" onundur."]},{"heading":"Afiş","points":["Sanatı sokaklara daşıyan: **afiş**.","Afişdə rəngli basım rahatlığı: **litografi**."]}],"number":2,"title":"Baskıresmin inkişafı","traps":[]},{"blocks":[{"points":["Boya **almaması** istənən yerlər oyulur. Kâğız boyanı oyulmamış yerlərdən alır.","Oyulmuş tahta kalıpdan resim basma: **Çin**.","Yüksek baskı növü: **ağaç gravür**. Ağaç gravürdə **daha çox baskı** alınır.","Ağac kəsimi: **enine ya da kılıcına**.","**Linol**: yumuşak dokulu, **ince detalları** oymaq asandır.","Baskı alətləri: **tahta kulp, baren, tahta ıspatula, tahta kaşık** (hamısı).","Əllə baskıda kâğıt: **ince, dokusuz, kuru**.","Qatı matbaa mürekkebini incəltmək: **resim yağı**.","Rəngli baskı: **eksiltmeli-eklemeli**."]},{"heading":"Baskı növləri","points":["**Edisyon**: plakadan alınan baskıların **tümü**.","**Baskıcı baskısı**: denemelərdən sonra əsas baskılara nümunə.","**Tıpkıbasım (reprodüksiyon)**: sənətçinin payı olmadan, mexaniki."]},{"heading":"Adlar","points":["Tarih-i Hind-i Garbî rəsmləri: **İbrahim Müteferrika**.","Tahta kalıpdan basanlar: **Dürer və Lucas Granach**.","1950-lər, tək kalıpla rəngli baskı: **Picasso**.","17. əsr Japonyada baskı **sanat** məqsədli idi."]}],"number":3,"title":"Yüksek baskı","traps":["Numaralandırmada **baskının yapıldığı yer** yazılmır.","Ağaç gravür üçün **çam** seçilmir (armut, akçaağaç, ceviz, şimşir seçilir).","Yanlış: \"boya alması **istenen** yerler oyulur\"."]},{"blocks":[{"points":["Başqa dildə adı: **Intaglio**.","Tərif: levhanın **yüksək hissələri təmizlənir**, pres ilə kâğıza köçür.","15. əsr Avropası, ilk çukur baskı: **bakır plaka**. Almanlar kâğıza ilk baskı: **1430-lar**.","Asitsiz çukur baskı üçün ən uyğun plaka: **bakır**.","Kâğıt: **lifli, su tuta bilən** baskı kâğıtları."]},{"heading":"Texnikalar","points":["Bakıra **burin** ilə kazıma: **oyma gravür**.","Büyüteçdə yuvarlaq kiçik oluklar: **noktalama**.","Səthi tırtıklayıb pürüzlendirmək: **mezotint**.","Kuru kazımada koyu ton: **paralel və çapraz** xətlər sıxlaşır.","Kenarları 35-45° törpüləmək: **pahlama**. Kâğıza və keçəyə zərəri önləyir."]},{"heading":"Adlar","points":["15. əsr Alman sənətçisi: **Albrecht Dürer**.","Fransız, ~73 plaka, dini hiss: **Jean Duvet**."]}],"number":4,"title":"Çukur baskı: metal plaka","traps":["**Gofre ve rölyef** geleneksel metal çukur baskı **deyil**.","Mürekkep verməzdən əvvəl plaka **ıslatılmır** (ısıtılır).","Bakır sülfatda bölgə **burin ilə əvvəlcədən kazınmır**.","**Gümüş** çukur baskı plakası deyil (çinko, bakır, pirinç, çelik var)."]},{"blocks":[{"points":["Plakanı asitdən qoruyan: **vernik** (lak). Məqsəd: levhanı **asit**dən qorumaq.","İlk asitli indirgeme, 1513: **Urs Graf**."]},{"heading":"Aquatinta","points":["Digər adı: **leke baskı**.","Reçine yapışsın deyə: toz reçineli plaka **ısı kaynağı** üzərinə.","Test kalıbı asitdə: **30 saniyə ilə 5 dəqiqə** arası.","Kalıb artıq mürekkep ala bilmir: **Creve**."]},{"heading":"Digər texnikalar","points":["**Yumuşak vernik**: zemin yağ\/don yağlı **balmumu** macunu. Doku: **kumaş, iplik, yaprak, ağaç kabuğu, folyo**.","Kâğızı boyalı\/boyasız kabartmaq: **gofre ve rölyef**.","Geniş fırça darbələri: **şekerli mürekkep**.","**Mumlama**: balmumu **koruyucu vernik** yerinə. Plaka **65 °C** qızdırılır.","**Sahte mezotint**: açıq ton zımpara və ya **demir kaşık** ilə ezilir."]}],"number":5,"title":"Asitle indirme","traps":["**Mezotint** asitle indirme texnikası **deyil**.","\"Baskı plakası kurumaya bırakılır\" baskı addımı **deyil**.","\"Çok renkli plaka ile tek renkli baskı\" çox rəngli çukur baskı **deyil**.","Sıvı sert zeminin dezavantajı: çizim zamanı **soyulmalar**."]},{"blocks":[{"points":["Çukur baskı ilk dəfə: **Almanya-İtalya**.","Profesyonelleşme: **16. əsr**.","Ucuz çoğaltma sanatı **demokratikleştirdi**.","Sanat kavramının kökləri: **Rönesans**. Üslubu təyin edən: **sanatçılar**."]},{"heading":"Röprodüksiyon","points":["Önəmli əsərlərin kopyası: **röprodüksiyon**.","İlk nümunələr: **Andrea Mantegna** atölyesi. Önəmli ad: **Marcantonio Raimondi**."]},{"heading":"Chiaroscuro","points":["**Işık və gölgənin sert kontrastı**, Rönesans sənətinin parçası.","Coriolano, \"Bakire ve Çocuk\": **Chiaroscuro**."]},{"heading":"Adlar","points":["**Maniyerizm**: İtaliya. Ən ünlü ressamı: **El Greco**.","\"Muhammed ve Keşiş Segius\": **Lucas van Leyden**.","\"Nemesis\": **Dürer**. \"Deniz Tanrılarının Savaşı\": **Mantegna**.","**Martin Schongauer**: derinlik və şəkil, **çapraz tarama** xətləri."]}],"number":6,"title":"Rönesans gravürü","traps":[]},{"blocks":[{"points":["Ən önəmli hadisələr: **Fransız Devrimi \/ Sanayi Devrimi**.","Küresel kültür səbəbi: **buhar gücü ulaşımda**.","Sanatın demokratikləşməsi: **litografi (taş baskı)**.","**Gravür**: fransızca, \"kazıma resim sanatı\"."]},{"heading":"Akımlar","points":["**Romantizm**: hayal gücü, ruhun özgürlüğü, modern devrin ilk addımı. Təmsilçi: **William Turner**, **Goya**.","**Empresyonizm**: Monet, ışığın anlık izləri, Japon ağaç baskısından təsir.","**Post-empresyonist**: **Cezanne, Seurat, Van Gogh**.","Şəkilli sual, Van Gogh: burulğanlı mavi gecə səması, sərv ağacı (**Yıldızlı Gece**).","Şəkilli sual, gravür nümunəsi: incə nöqtə və xətlərlə işlənmiş **ağ-qara mələk (melek) uşaqlar**. Rəngli yağlı boya tablolar gravür deyil."]},{"heading":"Adlar","points":["**Goya**: **akuatint** + **kuru iğne**. Seriyalar: Kaprisler, Savaşın Yıkımları, Boğa Güreşleri, Düşlemler.","**Dürer**: Almanyalı gravür ustası, ilk dəfə **asite yedirme və kuru kazı**.","\"Paris Gravürleri\", Notre Dame yaratığı: **Charles Meryon**."]}],"number":7,"title":"18-19. əsr və akımlar","traps":["**Akıllı telefon** 18-19. əsrin yeniliyi **deyil**.","Fotoğrafın təsiri **deyil**: \"ressamların mesleği olmuştur\"."]},{"blocks":[{"points":["Baskı: biçimlərin yüzeyə **çoğaltılması**. Ən belirgin xüsusiyyət: **kopyalama və çoğaltım**.","Texnikalar **kalıplarına görə** adlanır: yüksek, çukur, **düz**, elek baskı. Sanatda baskı: **14. əsr**.","**Düz baskı**: kalıp düz yüzeydir, **kazıma\/oyma yoxdur**. Ən ilkəli: **monotip**.","Növləri: **mono baskı, şablon baskı, litografi, ofset litografi**."]},{"heading":"Litografi və monotip","points":["**Litografi**: **kireçtaşı** üzərinə mum boya \/ yağlı kalem, **arapzamkı-nitrik asit** ilə sabitlənir. Prinsip: **yağ ilə su bir-birini itir**.","Tapan: Bavyeralı oyun yazarı **Aloys Senefelder**. Kireç taşına çizilən baskı: **taş baskı**.","**Honoré Daumier**: Charles Philipon üçün taş baskı ilə qəzet illüstrasiyaları.","**Monotip** (\"tek\"): ən qədim nümunə **17. əsr**, **Castiglione** (bakır plaka, **eksiltme**). 19. əsrdə **Degas** populyarlaşdırdı. Ucuz olduğu üçün savaş dövründə seçildi."]},{"heading":"Şablon, ofset, serigrafi","points":["**Şablon**: karton\/metal levhadan kəsilir. **Dişi kalıp**: dışı çıxır, içi boyanır. **Erkek kalıp**: içi çıxır, dışı boyanır.","**Ofset** = \"**dengeleme transferi**\". Tabaka ofset → kâğıt, **web ofset** → bobin\/rulo. Taşın yerini **metal** (çinko, alüminyum, bakır) aldı.","**Serigrafi \/ elek \/ ipek baskı**: **maskeleme**, **kauçuk lastik** ilə sıyırtma. İlk: 19. əsr **Fransa**. **Velonis** (1933-36) atölye, **Carl Zigrosser** güzel sanat formu etdi.","**Andy Warhol**: **serigrafi** (lokal rənglər), atölyesi \"**Fabrika**\"."]}],"number":8,"title":"Düz baskı","traps":["**Ağaç gravür \/ linol** düz baskı **deyil**.","Ofset: taş kalıp **istifadə olunmur**, taş baskı keyfiyyəti **alınmır**.","Dijital baskı ofsetdən **ucuz deyil** (maliyet yüksəkdir), amma sürətlidir, metal kalıp yoxdur."]},{"blocks":[{"points":["Özgün baskının mantığı: sənətçi kalıbı özü hazırlayır, **numaralanmış** baskılar alır.","Alternatif\/deneysel nümunələr: **monobaskı, fotogravür, kollagrafi, cellocut**.","**Monobaskı**: kalıpdan **tək** baskı, \"**ressamca baskı**\". Cam\/taş\/metal üzərinə **yavaş quruyan yağlı boya**.","**Degas**: monotip + **pastel**. **Gauguin**: \"**çizgi monotipi**\". William Blake də monotip edib. Eklemeli yanaşma: **Maniere noire**; eksiltmeli üçün plaka: **saydam akrilik**."]},{"heading":"Kalıp texnikaları","points":["**Kollagraf** = **kolaj + grafik**. Plakaya dokulu kâğıt\/malzeme yapışdırılır, **vernik**lə örtülür (mukavva, ince ağaç).","**Fotogravür**: **ışığa duyarlı film** zemin rolunda, **çinko və bakır**, boya **selülozik tiner**lə incəlir. Serigrafi ilə də edilir.","**Karborundum** = **silisyum karbür**, kuma bənzər **seramik**. Mürekkebə qatılır və ya plakaya sürülür.","**Chine collé**: **Japon kâğıdı \/ keten** kimi həssas yüzey, fərqli **arka plan rəngi**. Ən asan üsul: **nişasta tozu**."]},{"heading":"Adlar","points":["**Metal grafik**: **Rolf Nesch**, **Norveç 1925** (Kirchner-in yanında işləyib). Tel, çivi, demir tozu plakaya **lehimlənir**.","**Cellocut**: **Boris Margo, 1931**. **Aseton**la əridilmiş plastik. Bu gün **pleksiglas, lusit** (transparan plastik).","Dijital: **Fine-Art Print**. Üstünlüyü: **yüksək çözünürlük**."]}],"number":9,"title":"Özel (alternatif) baskı","traps":["**Kuru kazıma** alternatif baskı **deyil**.","Karışık texnikada chine collé **son** mərhələdə olur: zamk ıslak kâğıtda tökülür.","Fotogravür addımı **deyil**: \"kâğıdın arxasındakı qəzet kâğızına çizim\"."]},{"blocks":[{"points":["Baskı: **M.Ö. 105**, Çində **kâğıdın** tapılması. İlk baskılar: **damga\/ıstampa**.","Tək-tək hərf tökərək ilk baskı: Çinli demirçi **Pi Sheng**.","Japoniyada ilk ağaç baskı məqsədi: **Budizm**i yaymaq. Ən qədim nümunə: **Japon selvi** pagodalarında dualar (**darani**)."]},{"heading":"Rəng mərhələləri","points":["**Sumizuri-e** (~1600): siyah mürekkep, ən erkən.","**Beni-e** (1720-40): pembe. **Tan-e**: kırmızı + yeşil el boyaması. **Sarı**: 1750-lər.","**Nishiki-e** (1760-lar, **Edo** = Tokyo): çok renkli **brokar** resimler."]},{"heading":"Ukiyo-e və dövrlər","points":["12-16. əsr: iç savaşlar, imparatorluk baskıları, **Moğol baskınları** → inkişaf yox.","**Edo Dönemi (1615-1867)**: **Tokugawa** şogunları. **Chonin** = tüccar + zanaatkâr (orta sınıf).","**Ukiyo-e** = \"**yüzen dünya**\": gündəlik zevk və eğlence. Ən populyar: **tək baskı səhifələri** kimi. İlk böyük sənətçi: **Hishikawa Moronobu** (**Yoshiwara** bölgəsi).","**Hokusai**: \"Fuji Dağı'nın 100 Görüntüsü\". **Meiji** = modernləşmə, **Yoshitoshi** Batıdan təsirlənib."]}],"number":10,"title":"Japon baskı resmi","traps":["12-16. əsrin səbəbi **deyil**: \"Japonya'ya mürekkep getirilmemesi\".","Chonin **Konfüçyüsçü deyil**, zevk və lüks düşkünüdür."]},{"blocks":[{"points":["**Freud**: sənətçi \"nevrotik\/psikotik\" kateqoriyasından kənardadır, çünki hayal dünyasını **objektif formlara** çevirir.","**Modern**: Latınca **\"modo\"** (tam şimdi) → \"modernus\". Ən böyük etken: **Endüstri Devrimi**. Kökü: **Aydınlanma Çağı**. Geleneksel olanı **rədd** edir.","Modern baskıda **deneysel** yanaşma: gözlənilməz nəticələr sənətçiyə özgür sahə verir.","20. əsrdə baskı: deneysel + çoğaltılıb çox insana çatır → sənətçinin **tanınabilirliyi**."]},{"heading":"Akımlar","points":["**Dışavurumculuk**: \"dışarının izlenimi yerine **içerinin dışavurumu**\". Savaş yıkımı, adaletsizlik, makineləşmə. **Fovizm** (Fransa: Matisse, Derain, Vlaminck), **Die Brücke** (Almanya: Kirchner, Heckel, Nolde, Schmidt-Rottluff), **Der Blaue Reiter** (Franz Marc, **Kandinsky**, afişi **ağaç baskı**).","**Dada**: yetenək anlayışına tepki. **Duchamp** → \"**hazır nesne**\". Atık malzeme. **Hans Arp** → **rastlantısallık**.","**Sürrealizm**: **bilinçaltı və rüyalar**. Savaşdan sonra New York, **Hayter-in \"Atelier 17\"**-də gravür.","**Pop Art**: **1950-lər, İngiltərə və Amerika**; popüler kültür, tüketicilik, kitle iletişim. **Warhol**: Marilyn, Elvis, Liz Taylor → **serigrafi**."]},{"heading":"1960 sonrası və bu gün","points":["Deneysel baskılar + **dijital baskı** (daha çox insana çatır). Baskı: **sanatsal, politik, protest, eğitsel** vasitə.","**1980-1990**: savaş, siyaset, ırkçı söylemlər. **Baskı enstalasyonu**: **Post Modern**, 1990-lar, 3 boyutlu heykel formu.","**Käthe Kollwitz**: \"Köylüler Savaşı\", \"Çift Sürenler\" (kapitalist sistem). **Jaune Quick-to-See Smith**: Kızılderili mitləri."]},{"heading":"Türk sənətçilər","points":["Türkiyədə baskı **Sanayi-i Nefise** ilə başladı, yayğınlaşma **20. əsr**. **Léopold Lévy** gəlincə atölye yenidən, başına **Sabri Berkel**.","**Ergin İnan**: renkçi, **deformasyona uğrayan figürler**; \"portreler, eller, mektup, yaratılış\".","**Hasan Kıran**: kavramsal **baskı-enstalasyon**, talaş və spirallər. **Müjde Ayan**: linol, serigrafi, **litografi**, ton açıqdan tündə."]}],"number":11,"title":"20. əsr baskı sanatı","traps":["Modern sənətin xüsusiyyəti **deyil**: \"natüralist, dışsal olanı ölçüt alan geleneksel anlayış\".","\"İzlenim\" → Empresyonizm; \"içerinin dışavurumu\" → **Dışavurumculuk**. Qarışdırma."]},{"blocks":[{"heading":"Başlanğıc","points":["Başlanğıc: **İbrahim Müteferrika**, **1730**, \"**Tarih-i Hind-i Garbî**\". Kalıplar **şimşir**ə oyulub (yüksek baskı) + **çukur baskı** ilə dünya xəritəsi.","İlk taş baskı atölyesi: **Hanri Kayol** (Fransadan), kitabı: \"**Nuhbetü't-talim**\" (askeri). 1836: Beyoğlunda **Kayol kardeşler**. İlk texnika: **taşbaskı**.","**Sanayi-i Nefise** (1882): gravür atölyesi, ilk hoca **Artur Napier**. 1924-də bağlandı (\"zanaat atölyesi\" kimi qaldığı üçün)."]},{"heading":"Cumhuriyet dövrü","points":["**Léopold Lévy** öncülüyündə yenidən açıldı, başına **Sabri Berkel** → gravür + **ipek baskı + monotip**.","2-ci kurum: **Gazi Eğitim Enstitüsü Resim İş** (1932, Ankara). 3-cü: **Tatbiki Güzel Sanatlar** (1957), gravür hocası **Mustafa Aslıer**.","Lévy yetişdirdi: Nuri İyem, Avni Arbaş, Selim Turan, Nejad Devrim. İlk kuşak: Sabri Berkel, Nurullah Berk, Turgut Zaim, Ercüment Kalmık."]},{"heading":"Sənətçilər","points":["**Aliye Berger**: **ilk Türk kadın baskıresimci və gravürcü**; öz presi var idi; kasap kâğıdı, zımpara, tülbent.","**Mustafa Aslıer**: \"**Özgün Baskıresim**\" terminini işlətdi; müəllimi **Şinasi Barutçu** (monotip, linol).","**Mürşide İçmeli**: Anadolu insanı, soyut figüratif, insan yığınları, **ağaç gravür\/rölyef**.","**Süleyman Saim Tekcan**: **IMOGA** (ilk baskıresim müzesi; məqsəd: özgün baskı bilinci), üniversitet atölyeleri.","**Asım İşler**: Paris **Atelier 17** → **viskosite və kolaj gravür**."]}],"number":12,"title":"Türkiyədə baskı resim","traps":["**Mustafa Aslıer** ilk kuşak **deyil**. **İbrahim Çallı** Lévy-nin yetişdirdiyi **deyil**.","\"Tarih-i Hind-i Garbî\" → Müteferrika; \"Nuhbetü't-talim\" → Kayol atölyesi. Qarışdırma."]},{"blocks":[{"points":["Gravür: yüzey **kazınır**, mürekkep **çukurlara** dolur, presle kâğıza. Osmanlını əks etdirir: **XV. əsr ortası → XIX. əsr sonu**.","**Yazmacılık**: Anadoluda taxta kalıbı oyub kumaşa basmaq (gravürlə eyni məntiq). Padişah mühürlərini edən: **hakkak \/ kalemkâr**.","Ən çox çəkilən mövzu: **İstanbul**. XV-XVI. əsr: **kuş bakışı \/ uzun panorama**. Sanayi-i Nefise-də gravür bölümü: \"**hakk**\"."]},{"heading":"Xronologiya","points":["Batı resmi ilə tanışlıq: **Fatih Sultan Mehmet**. **Angionello**: Fatihin səferində əsir, \"**Historia Turchesca**\". **Vavassore** (1518-72).","**Nikolay**: 60 ağaç gravür. **Vanmour**: bakır, \"**Osmanlı Kıyafet Albümü**\". Ilk Osmanlıca gravür: **Tunuslu Hacı Ahmet** dünya xəritəsi (elma ağacı, 6 kalıp).","**Melchior Lorichs** (Danimarkalı): **21 parça, 11 m** panorama + Kanuninin 4 portreti.","**IV. Murat**: **Kâtip Çelebi**-nin \"**Cihannüma**\"sı (38 çizim). **Lale Devri**: 1729 matbaa (**Müteferrika**), ilk **Marmara** xəritəsi.","**III. Selim**: L'espinasse (**Kâğıthane, Sadabad**), Jean Baptiste Hilair. **II. Mahmut** (1808-39): Batılı sənətçilər."]},{"heading":"XIX. əsr","points":["**Oryantalizm**: Batılıların İslam dünyasına tavrı (Theophile Gautier). Pera atölyelərlə dolu.","Gravürün yerini **fotoğraf** aldı (belgesel xüsusiyyət keçdi).","**Thomas Allom**: \"Constantinople and the Scenery of the Seven Churches...\", **94 gravür**. **Bartlett**: Süleymaniye, romantik doğu. **Joseph Schranz** (Alman): boğaz panoramaları.","Amaca görə **7 başlık**: pitoresk seyahat, seyahatname, hatırat (souvenir), kıyafet albümleri, karikatür, haber görselleri, ürün gravürleri.","Saray gravürləri: **Birun, Enderun, harem** halkı. Mekânlar: harem, cami, hamam, Haliç, kahvehane, berber, mezarlık."]}],"number":13,"title":"İstanbul gravürləri","traps":["Kateqoriya **deyil**: **sokak hayvanları**. Mekân **deyil**: **savaş meydanları**.","Avropalıların gəlmə səbəbi **deyil**: \"Avrupa'nın sanatçıları dışlaması\".","Cihannüma müəllifi **Kâtip Çelebi**, Müteferrika isə **əlavələr** edib."]},{"blocks":[{"points":["**Ekslibris**: **Latınca** \"kitaplarından \/ kütüphanesinden\". İngiliscə **bookplate**, Almanca **Bücherzeichen**.","Kitabın **ön kapağının iç kısmına** yapışdırılan **mülkiyet** etiketi. Mövzular: mitoloji, din, tarih, müzik, doğa, aile, kadın, meslek, gerçeküstücülük.","İşlevlər: aidiyet, ödünc alana \"geri getir\", **hırsızlığa qarşı**, **sanatsal nesne**, tarixi sənəd. Tək işlevlə məhdud deyil."]},{"heading":"Tarix","points":["Ən qədim: **M.Ö. 1400, Mısır Kralı III. Amenhotep**; Asurbanipal (M.Ö. 600). Matbaadan əvvəl **armalar**.","Avropada ilk: **15. əsr Almanya** (papaz **Johannes Knabenberg**, \"kirpi\"). Altın çağ: **16. əsr Almanya**, **Dürer** (ağaç baskı), \"küçük öğretmenler\".","19. əsr sonu → **koleksiyonculuq**. **1891 Londra**: \"Ekslibris Topluluğu\". Koleksiyoner: müxtəlif ilgi alanlı insanlar.","Üslub: 15. əsr **gotik**, 16. **Rönesans**, 17. **Barok**, Art Nouveau (1890-1910) **dekoratif**."]},{"heading":"FISAE və Türkiyə","points":["**FISAE** = Uluslararası Ekslibris Dernekleri Federasyonu. Qaydalar: ön kapak içi, **13x13 cm**-dən böyük olmaz, siparişlə, sahibinin adı, **\"Ekslibris\" \/ EXL** yazılır, **yaşayan** insan üçün.","Simgələr: **X** yüksek, **C** çukur, **L** düz baskı (1958 Barselona, 2002 Frederikshavn). Resimdən fərqi: **yazı**.","Türkiyədə ilk ekslibris: **Batılı öğretmenler**. **Hasip Pektaş**: **1997 AED** (indi İstanbul Ekslibris Derneği), \"kitabın kartviziti ya da tapusu\".","**2008**: **İMOGA** bünyəsində **İstanbul Ekslibris Müzesi**. Türkiyədə **dijital** texnika daha çox."]}],"number":14,"title":"Ekslibris","traps":["Ekslibrisin işlevi **deyil**: \"kitapların satışını artırma\".","Ölən insan üçün ekslibris **edilmir** (yalnız anısına).","Ekslibris üçün **renkli kâğıt** tercih edilmir, kâğıt da çox qalın olmamalı."]}]},"Reklam Grafiği":{"intro":{"heading":"Əsas açar: \"değildir\" sualında pul və talep tələsi","points":["**Maliyet, fiyat, talebi artırmak, istihdam** variantı çox vaxt \"değildir\" cavabıdır (tipografi, metin, reklamın etkisi, etik).","İstisna: üretici reklamla **satışı artırmaq** istəyir, üretici tərəfdən etki **istihdam** ilə bağlıdır.","Reklamın 3 əsas işi hər yerdə təkrarlanır: **bilgi vermek, ikna etmek, dikkat çekmek**."]},"quick":["En eski reklam → tellal · İlk tekrarlama → Mısır taşları · Kitlesel → matbaa","Bant reklam → səssiz TV · Fuar → karşılıklı etkileşim · Broşür → bahalı kitab","Funksiya: bilgilendirme, ikna, hatırlatma, değer katma · Örgütleme deyil · Japonya → özür havası","Zorlayıcı → \"Hemen al\" · Tavsiye\/davet → \"Fırsatı kaçırmayın\" · Muhalif başlık yoxdur","Peirce → təməl, yorumlayıcı · Barthes → biçim\/içerik · Augustine → ilk · Semeion → gösterge","Tipografi → bilgi, ikna, dikkat · Gotik → ilk matbaa · Talep\/maliyet → değil","Gazete → tiraj · Kamu duyurusu → zorunlu · BİK → resmi ilan","Amblem → sözsüz · Logotype → yazı · Kare → sağlam · Tırnaklı → köklü · Küçük harf → samimi","İlk aşama → problemin tanımı · Gazete → Mondrian · Dergi → imge ağırlıklı · Taslak → dışavurumcu","Cel → soğan zarı · Cut-Out → stop-motion · Meisel → Vogue · De Meyer → teatral · %60 → fotoğraf","Ambalaj → satıcı · Sanayi Devrimi → dönüm noktası · Üçgen\/Uyumsuzluk → değil · Hedefli reklam → dijital","Billboard → 200x350 · CLP → 1185x1750 · Megalight → 241×324 · Silindir → 6 poster · Kuleboard → 10 m","Maslow → fizyoloji…öz gerçekleştirme · Dokunsal → değil · Onboard → uçak · Bez çanta → sürdürülebilir"],"units":[{"blocks":[{"points":["**Reklam**: bedeli kim ödədiyi bəlli, kitle iletişim araçlarından yer və zaman alıb halka tanıtmaq.","Ən köhnə reklam: **sokak tellalları**. İlk təkrarlama: **Mısır, aralıklı taşlar üzərində**.","Kitlesel iletişim oldu: **matbaanın icadıyla**.","Tüketicinin məqsədi: **kullanım biçimiyle ilgili bilgi sahibi olmak**.","Reklam ortamı: **billboard**. Ortam seçimində: ürünün niteliyi, hedef kitle, amaç, **bütçe**."]},{"heading":"Növlər","points":["Hareketli açık hava: **balonlar**. Sabit: billboard, cephe giydirme, pankart, tabela.","Çatı panosu, afiş, tabela, karton adam → **açıkhava reklamları**.","**Bant reklam**: TV-də səssiz, axını kəsmədən ekranın bir yerində.","**Hareketli reklamlar**: doğrudan satış və program destekleme.","**Fuar**: toplu organizasyonda hedef kitleyle karşılıklı etkileşim.","**Broşür**: görsel çox, yüksek maliyetli tanıtım kitabı.","Gazete reklamının maliyeti: alan, kâğıt türü, yayın sayfası, renk."]}],"number":1,"title":"Reklam və ortamlar","traps":["**Mal ve hizmetlerin satılması** reklamın amacı deyil (tanıtmaq amacdır).","**Radyo reklamları** reklam grafiği kapsamına girmir.","**Yüz yüze satış** reklam tərifində yoxdur.","**Ürünlere ham madde sağlamak** üreticinin amacı deyil.","**İnternet** basılı reklam aracı deyil. **Balonlar** sabit açık hava deyil.","**Tasarım biçimi** gazete maliyetini təyin etmir. **Firmanın faaliyet alanı** ortam seçimində nəzərə alınmır."]},{"blocks":[{"points":["Əsas funksiyalar: **bilgilendirme, ikna etme, hatırlatma, değer katma**.","**İkna etme**: ayırıcı özelliyi öne çıxarmaq, tercihi dəyişmək, denemeye yönlendirmek.","Yanıltıcı slogan: **\"En mükemmel, en eşsiz tat\"**.","Romantizm, manzara, şiir, sükûnet, \"özür dileme havası\" → **Japonya**.","Yaşıl İslamda kutsal, beyaz Hong Kongda ölüm, qara Anadoluda yas → **reklam ve kültür ilişkisi**."]}],"number":2,"title":"Funksiyalar, etika, toplum","traps":["**Örgütleme** reklamın funksiyası deyil. **Çalışan memnuniyeti** də deyil.","**Reklamın zorlayıcı olması** aldatıcı reklam növü deyil.","**Reklamın maliyeti ve fiyatı** insanlara etkisi deyil.","**İmaj kazandırma** bilgilendirme ilə anlatılmır.","**Toplumsal istihdam** kültürel reklamda nəzərə alınmır. **Bireysel alış veriş oranları** yabancı ölkədə gereksizdir.","Uşaq reklamı: \"aile ortamı dışında yer almamalı\" qaydası **yoxdur**.","**İstihdama katkı** etik tənqid deyil. \"İnsanları bilgilendirir\" olumsuz sonuç deyil.","Üretici etkisi: **tatmin** deyil. Sosyolojik etki: **ürünle tatmin duygusu** deyil.","Dini reklamda \"hiyerarşide yüksek konum\" tatmini **yoxdur**.","Bilinçaltı reklamda mesaja **bilinçli tepki verilmir**."]},{"blocks":[{"points":["**Reklam metni**: mesajı amaca uyğun ileten hər yazılı və görsel ifadə.","Tərkibi: **başlık, alt başlık, gövde metni, slogan** (brief yox).","**Başlık**: ən üstdə, qalın\/böyük hərf, dikkat çeker.","**Gövde metni**: fikri açıqlayır, ümumi bilgi, mesaj net.","**Logo**: markanı temsil edən, grafiksel sembol. Kurumsal imzadır.","Dil: **sade, kısa cümle, günlük konuşma dili**. Dil hedef kitle, medya, ürün, metin türü ilə dəyişir."]},{"heading":"Növlər","points":["**Anlatı metni**: dramatik hikâye, mizah, romantizm, hüzün.","**Açıklayıcı\/Bilgilendirici**: teknik bilgi yox, çox yalın.","**Zorlayıcı başlık**: \"Hep daha iyiyi iste!\", \"Hemen al, pişman olma\".","**Tavsiye\/davet başlığı**: \"Aramıza katılabilirsiniz\", \"Bu fırsatı kaçırmayın\".","Başlıklar: zorlayıcı, seçici, durum, meraklandırıcı, haber tarzı, fayda, sorulu."]}],"number":3,"title":"Reklam metni","traps":["**Benzetmecilik** metnin özelliyi deyil.","**Muhalif başlık** yoxdur.","Özgünlükdə **geçmişe öykünmek** səhvdir.","**Üretim maliyeti ve satış fiyatı** nəzərə alınmır, sual da deyil.","**Edebi süsleme, uzun betimleme** olmamalıdır.","Logo hər reklam üçün **yenidən üretilmir**.","**Brief** metnə daxil deyil. **Radyo** basılı metin üçün deyil.","**Reklam sloganı** anlatım dilini etkilemez."]},{"blocks":[{"points":["**Gösterge**: başqa şeyin yerini tutan, kendi dışında bir şey göstərən.","**Göstergebilim**: işaret sistemlərini sözdizim və anlambilim çərçivəsində inceler.","**Semeion**: Yunanca, \"gösterge\".","**Metafor**: \"gibi göstermek\".","**Düz anlam**: olduğu kimi algılanan ilk anlam. **Yan anlam**: kişisel, kültürel təcrübəyə görə.","Anlamına görə: **sav gösterge**. Benzerlik ilə: **görüntüsel gösterge**.","\"Çalar saat\" → **kahve**. \"Göydə qırmızı balon\" **bulaşık deterjanında** işlənməz."]},{"heading":"Adlar","points":["**Peirce**: çağdaş göstergebilimin təməli; gösterge, gösterilen, yorumlayıcı.","**Barthes**: biçim və içerik; düz və yan anlam.","**Augustine**: göstergebilimi iletişim aracı sayan ilk şəxs.","Çalışanlar: Aristoteles, Locke, Lambert, Saussure."]}],"number":4,"title":"Göstergebilim","traps":["**David Hume** göstergebilimdə çalışmayıb.","**Yorumlayıcısına göre** dil dışı gösterge türü deyil.","**Önerme** nesnesine göre gösterge deyil (ikon, görüntüsel, belirti, simge).","**Index** Barthesin termini deyil."]},{"blocks":[{"points":["Amaçları: **bilgi aktarma, ikna etme, dikkat çekme** (I, II və III hamısı).","Ən doğru: bunlar + **yaratıcı uygulamalarla fark yaratma**.","Yeri və önəmi **reklam stratejisine göre** dəyişir.","Diqqət: **yazı tipi seçimi, sıradüzen, uygunluk**.","Yazı tipi seçimi: marka kimliği, ürün biçimi və içeriyi, reklam stratejisi.","**Hiyerarşi**: unsurlar mesaj və uygunluğa görə önəm sırasında.","Yaratıcı uygulama: **ürüne özel yazı tipi tasarımı**.","Gutenberg öncəsi: **işlevsel metinsel unsur**. Erkən matbaa ilanı: **Gotik**."]}],"number":5,"title":"Tipografi","traps":["\"Okunur yazı tipindən uzak durmaq\" qayda **deyil**.","**Ürün amblemi** metinsel anlatım deyil.","**Maliyeti azaltmak, kafa karıştırmak** tipografinin amacı deyil.","**Talebi artırmak** yazı tipi seçiminin önəmi deyil, sıradüzen səbəbi də deyil.","**Birden fazla yazı tipi seçmek** diqqət ediləcək hüsus deyil.","Yazı tipi **müşteri talebine** bağlı deyil."]},{"blocks":[{"points":["**Mecra**: reklamın yer alıb sərgiləndiyi bütün alanlar.","Geleneksel: **dergi, gazete, radyo**, televizyon. Tek yönlü, böyük kitlə, hızlı.","Ən çox seçilən yazılı basın: **dergi və gazete**.","Yazılı basın: **güvenilir, kalıcı, durağan**.","Gazetenin üstünlüyü: **yaygın, tirajı yüksək**. Dergi: baskı yüksək, arşivlənir, hedef kitle seçimi.","Gazete reklam türleri: **teşhir, seri ilan, kamu duyurusu, ilave**.","**Teşhir**: güclü fotoğraf, bold başlık, şerifsiz font.","**Kamu duyurusu**: qanunla zorunlu; kiçik punto, metin çox, çizgi, tek renk.","**Basın İlan Kurumu**: resmi ilanları gazete və dergidə yayımlamaq.","**El ilanı**: tek yaprak, kampanya dönəmi, ucuz."]}],"number":6,"title":"Geleneksel mecralar","traps":["**Anında feedback, tıklanma sayı** geleneksel mecraya aid deyil.","**Web sayfaları** geleneksel deyil. **El ilanları** dijital deyil.","Teşhirdə \"rəng nadir, tek siyah\" **yanlışdır**.","Kamu duyurusu və seri ilanda **güclü, bol fotoğraf yoxdur**.","Dergi: \"baskı kalitesi düşük\" üstünlük **deyil**.","Basılı reklamda **ses** olmur.","El ilanı **çok sayfalı deyil**."]},{"blocks":[{"heading":"Adlar","points":["**Amblem**: söz olmayan, soyut\/nesnel görüntü və ya hərflə simge.","**Logo**: kurum adının hərf, söz, görüntü ilə sembolize edilməsi.","**Logotype**: xüsusi tipografi ilə yazılmış ad.","**Tekli\/monolitik**: hər yerdə eyni ad, renk, yazı karakteri.","**Markalanan kimlik**: alt markalar, kurum kimliyi markadan ayrı."]},{"heading":"Renk və forma","points":["Qırmızı: ateş, kan, aşk, tehlike. Mavi: **gökyüzü**. Sarı: **gün ışığı**.","Yaşıl gıda → **organik, doğal**. Beyaz: saflıq, **Doğu Asyada ölüm**.","Qara olumlu: şıklık, zarafet, güç, ciddiyet.","Kare → **sağlamlık**. Daire → sonsuzluk, süreklilik, güvenlik, sevgi.","Tırnaklı font → **köklü**. Küçük harf → **enerji, samimiyet**."]}],"number":7,"title":"Kurumsal kimlik","traps":["**Şirket ortakları** görsel kimlik elementi deyil.","Qırmızı **gökyüzü** ilə bağlı deyil.","**Korku** qaranın olumlu çağrışımı deyil.","Daire **stabil\/durağan, inşaat** demək deyil."]},{"blocks":[{"points":["**Enformasyon**: dar kapsamlı konuya aid **derlenmiş bilgi parçası**.","**Grafik tasarım** = iletişim tasarımı, görsel iletişim tasarımı: mesaj və görüntü ilə bilgini hedef kitleye çatdırır.","Sanayi Devrimindən əvvəl hər aşamanı **zanaatkârlar** edirdi (kişisel estetik).","Afişlər konuya görə 3: **sosyal, reklam-ticari, kültürel**.","**Reklam afişi**: ürün\/hizmeti **ticari** tanıdır (gıda, moda, endüstri). Ögeləri: **tipografi, illüstrasyon, fotoğraf**.","Yeri: **dış mekân** — cadde, sokak, terminal, gar, metro\/otobüs durağı. İlk illərdə **illüstrasyon**, edən **ressamlar**."]},{"heading":"Süreç və taslak","points":["Tasarım süreci: **problemin tanımı → bilgi toplama → yaratıcılık ve buluş → çözüm bulma → uygulama**.","İlk aşama: **problemin tanımlanması**. Son aşama: **uygulama**.","**Taslak**: üretim öncesi görünüm haqda bilgi verən rehber çizgiler, karalamalar. Ən **uzun** tutulmalı evrədir.","Taslak türleri: **Mondrian, imge ağırlıklı, metin ağırlıklı, çerçeveli, sirk, çok panolu, siluet, tipografik, rebus, harf biçimli**.","**Gazete tasarımları → Mondrian**. **Dergiler → imge ağırlıklı**.","Taylor: taslaklar yaratıcılığın **dışavurumcu** aşamasındadır.","Görsel öğeler: **çizgi, yön, doku, oran-orantı, renk**. Afiş **basit və net** olmalı."]}],"number":8,"title":"Reklam afişi tasarım süreci","traps":["**Serbest taslaklar** taslak türü deyil.","**Yetenekçi** Taylorun 5 yaratıcılıq aşamasından deyil.","**Kararlılık (resolvity)** yaratıcılığın özelliyi deyil.","**Ses** görsel anlatımsal aktarım aracı deyil.","Şarkıcı\/konser afişi **reklam afişi deyil** (kültürel afiş)."]},{"blocks":[{"points":["1900-lərin əvvəli **foto-gravür** baskı → rəngli, keyfiyyətli görsel; şüar: **\"Bir resim bin sözcüğe bedeldir\"**.","Reklam **satışı sağlamayı, artırmayı veya korumayı** hədəfləyir.","**İllüstrasyon**: metin və fikirləri tasvir\/açıqlamaq üçün ən yaygın **resimleme** türü.","Reklama katkı: bakışı yakalamak, **izlenme sırasını** yönləndirmək, hızlı\/doğru algı, **çağrışım**.","Fərqli illüstratorların **özgün** yaratımları izleyiciyə estetik **haz** verir."]},{"heading":"Türler","points":["**Reklam**: ürün, ambalaj illüstrasyonu.","**Basın-Yayın**: editöryal, **çocuk kitabı**, çizgi roman.","**Bilimsel\/Teknik**: tıbbi, adli, teknik, bilimsel. **Konsept sanat**: fantastik. **Moda**."]},{"heading":"Animasyon","points":["**Animasyon**: çizim, bilgisayar grafiği və ya statik nesne fotoğraflarını **ardışık dizi** edib film yapma.","Gücü: **eğlenceli izlence + sınırsız yaratıcılık** + ekonomik fayda; **viral** potensial.","Özellikləri: ekonomiklik, zaman tasarrufu, **zamansızlık**, basitleştirme, kolay algı, hatırlanabilirlik, yüksek etkileşim.","Mesajı **basitleştirilmiş formda** verir; \"deterjan yiyen lekeler\" kimi **soyut** fikrə biçim verir; **markalar** aracılığıyla benzersiz kimlik yaradır.","Karakter: marka ilə özdeşləşir, **kopyalanamaz (intihal edilemez)**, gerçekçi olmaq məcburi deyil. Ünlü yıldızın kampaniyası onun **kariyeri** ilə sınırlıdır.","**Cel** = soğan zarı: yarı saydam yapraqlara elle, ışıklı masada.","**Flipbook**: səhifələr hızla çevrilir → hareket illüzyonu (çizim və ya foto).","**Cut-Out (kes-çıkart)**: **stop-motion** türü; kâğıt, karton, kumaş, metal düz figürlər.","**2D**: vektör, sadə rig. **3D**: iskelet, render. **Hareketli grafik**: vücut mekaniği\/oyunculuq lazım deyil."]}],"number":9,"title":"İllüstrasyon və animasyon","traps":["**Üretiminin uzun zaman alması** illüstrasyonun katkısı deyil.","**Tetrad** animasyon–reklam ilişkisi türü deyil.","**Engraving (gravür)** animasyon tekniyi deyil.","Çocuk kitabı illüstrasyonu **reklam** deyil, **basın-yayın** qrupudur."]},{"blocks":[{"points":["**Fotoğraf**: Sanayi Devrimi ilə tapılan, **görsel kültürü** yaradan, mesajı doğrudan və hızlı ötürən araç.","**Reklam**: reklam verəndən tüketiciyə axan **iletilerin bütünü**; araşdırma, bütçe, zaman, mecra qərarları və grafik hazırlığı.","Görsel bileşen: **fotoğraf, grafik tasarım**. Sözel: **metin, tipografi, simge-sembol**.","**Ana başlık**: ən önəmli, birkaç kelime. **Alt başlık**: başlık ilə metin arasında körpü. **Gövde metin**: uzun açıqlama. **Slogan**: akılda kalıcı, harekete geçirir.","**Tipografi**: metinlərin **biçimsel özelliklerini** ele alan disiplin."]},{"heading":"Tarix","points":["20. əsr əvvəli: **Piktoryalizm**; **Edward Steichen**, **De Meyer** reklamı sanatla birləşdirdi.","**Adolph De Meyer**: fon aydınlatması, yumuşak netlik, teatral qadın gözəlliyi.","1920–30: basılı yayının yüksəlişi. 1960: **Pop Art**, postmodernizm → ürünün **estetik imajı**.","1980: idealize gözəllik yox, **gündelik hayatın doğallığı**.","**Steven Meisel** (1988-dən **İtalya Vogue** kapakları): hikâyəli, kurgu belgesel seriler.","**Barthes** (\"Image, Music, Text\"): fotoğraf ikincil düzeydə **yan anlam** daşıyır."]},{"heading":"Amaç və nitelik","points":["Tercih səbəbi: **gerçeklik, kolay okunurluk, hedef kitleye çabuk ulaşma**.","Dergi ilanlarının və panoların **ortalama %60-ı** fotoğrafik.","Yazıya üstünlük: bütün oxunmadan anlaşılır, **hatırlanması kolay**.","İş üsulu: əvvəl **satış analizi**, sonra texniki imkan + yaratıcı fikir.","Amaçlar: ilgi çəkmək, mesajı anında\/net vermək, ilgini **başlık və metine** yönləndirmək, zor fikri açmaq, **inandırıcılık**.","Nitelik: sade, açık, gereksiz detay yox; **\"ısınma süresi yoktur\"**; görsel ürünü **arxa plana atmamalı**."]}],"number":10,"title":"Reklam fotoğrafı","traps":["**Maliyetinin ucuz olması** fotoğrafın tercih səbəbi deyil.","**Zaman kaybını önlemek, maliyeti düşürmek** reklam fotoğrafının amacı deyil.","\"Fotoğraf yazıdan **daha hızlı üretilir**\" üstünlük deyil.","Reklam fotoğrafında nesne haber\/belgeseldəki kimi **doğallığında çəkilmir**."]},{"blocks":[{"points":["Ortaya çıxışı: yiyecekləri **koruma, saklama və taşıma** ehtiyacı. İlk material: **yaprak**; sonra çömlek, ahşap, cam, dokuma.","Ən önəmli **dönüm noktası**: **Sanayi Devrimi**.","İşlevlər: **koruma, tanıtma, bilgilendirme, kurum kimliği, reklam**. Ambalaj **\"satıcı\"** rolunu üstlenir.","Son məqsəd tekdir: **ürünü sattırmak**.","Material: **cam, metal, plastik, kağıt, karton**.","Ən önəmli kriter: **sade, anlaşılır, satın almaya teşvik edici**; uğur üçün **özgün və dikkat çekici**.","Tasarımcı **estetiğe** dikkat etməlidir. Qırmızı rəng → **tatlı** tat hissi."]},{"heading":"Öğe və ilkələr","points":["Tasarım öğeleri: **nokta, çizgi, leke (değer), yön, form, ölçü, oran-aralık, doku, renk**.","Tasarım ilkeleri: **denge, orantı, uyum, hiyerarşi, bütünlük, ritim, boşluk, renk, desen, vurgulama**.","Üretim süreci = son aşama; tasarımcı **baskıya hazırlar**, sonra məsuliyyət **ambalaj üreticisine** keçir. Üretim yeni **tasarımlama** sürecinin başlanğıcıdır."]}],"number":11,"title":"Ambalaj tasarımı","traps":["**Üretim işlevi** ambalajın işlevi deyil.","**Üçgen** tasarım öğesi deyil. **Uyumsuzluk** tasarım ilkesi deyil.","**Baskı süreci** tasarım öncəsi iş deyil.","**Kalite ve değer algısı** üretim aşamasında baxılan hüsus deyil.","Logo **tat duygusunu artırmır**. Sembol-simgenin amacı **dikkat çekme** deyil.","İmtahan cavabı: **Doku** ambalajı oluşturan öge deyil (amma öğe siyahısında var)."]},{"blocks":[{"points":["**Web 2.0** ilə rəqəmsal dünya; dünya istifadəçi sayı **4.62 milyar**. Nümunə: **TEMA, WWF**.","Dijital və geleneksel arasında **tasarım fərqi yoxdur**.","Əsas fərq: daha çox insana **daha qısa sürədə, eyni anda**; **daha ucuz**; beğeni\/yorum görünür.","Başarılı mesaj: kolay algılanır, dikkat çeker, ilgi uyandırır, **akılda kalıcı**; **olumlu ikna** edir.","Elementlər: **başlık, görsel, metin, slogan** (+ firma logosu). Başlık **kısa**, yormayan.","Metin: **gerçekçi, konuşma diline yakın, sade, anlaşılır**.","**Yaratıcılık**: daha önce yapılmamış fikrin **uygulanması**; **ilginç olması** yaratıcılığa katkıdır. Yaratıcı olmayan → **tekrara düşmüş**."]},{"heading":"Növlər","points":["**Geleneksel**: TV, radyo, gazete, dergi, açık hava, sinema, doğrudan postalama, fuar. Bahalı, az insana, **uzun** sürədə.","**Dijital**: internet, sosyal medya, mobil, **advergaming** (oyun içi reklam).","İnternet reklamı: e-posta, **rich media, pop up, hedefli reklam**, içerik sponsorluğu, seri ilan, profil, advertorial, arama motoru, affiliate.","Sosyal medya (Facebook, Instagram, Twitter): **hızlı olumlu\/olumsuz geri dönüş**; tercih səbəbi **daha çok insana daha hızlı**."]}],"number":12,"title":"İnternet və sosyal medya","traps":["**Hedefli reklam** geleneksel deyil. **Açık hava** internet reklamı deyil.","**Yüksek bütçeli olması** internet reklamının avantajı deyil.","**Çok karmaşık olmak** amac deyil. Metin **süslü** olmamalı.","**Kurum** iletişim süreci deyil. **Müşteri** tasarım ögesi deyil. **Reklam grafiği** görsel iletişim unsuru deyil.","**Ajans** iyi çözümlenmiş reklam grafiğinə nümunə deyil."]},{"blocks":[{"points":["Digər adları: **outdoor, out-of-home (OOH)**. Görsel → tasarım, teknik → malzeme, reklamcılıq → hedef kitle-ürün bağı.","Seçim faktoru: konum, kitlə **yaya\/yolculuk halında**, boyut, yerleşim, malzeme.","**Billboard**: **200x350 cm**; amaç **marka isminin tanınması**; çerçeve dışı imge (**Plus**).","**Raket (CLP, city-light-poster)**: **1185x1750 mm**, yaya-araç yoğun yer.","**Megalight**: **241×324 cm**, yakın\/uzak mesafe; meydan, AVM, cadde.","**Giantboard**: bir neçə billboard **yan yana**.","**Silindir**: meydan\/kavşak, **6 görsel alan**, **360°** dönə bilir.","**Parapet**: **inşaat, restorasyon** önündə geniş cephe.","**Mesh**: **delikli vinil branda**, dijital baskı, hafif, dayanıklı.","**Megaboard**: içten aydınlatmalı, yüksək iskelet. **Kuleboard**: **10 m**. **Yol panoları**: araçlı yolcu üçün.","**Outdoor TV**: **dijital** ürün; gün ışığında görünən ekran, **klima**, koruyucu cam\/çerçeve.","**Pole banner** = direk reklamı: **çox sayda** direk alınmalıdır."]},{"heading":"Malzeme və tasarım","points":["Toplu taşımanın **dış yüzeyi → açık hava**, **iç mekânı → iç mekan** reklamı.","Havalimanı: megalight, durak raket, TV, alınlık, duvar, konveyör üzeri pano, süper pano, pole banner.","Tabela: katmanlı, ışıklı, eğik, yuvarlak, kabartma, yüzeyden taşırma.","Kağıt: **ışık geçirgenliği güçlü, uzun ömürlü, geniş ebatlı, yırtılma və sürtünməyə** dayanıklı; özəl kaplama.","Lightbox: kâğıt yerinə **ışıklı kumaş**.","Kiralama, baskı, dağıtım, təmizlik, arıza → **alanda hizmet veren firmalar**.","Tasarım: ilgi çekici, **ikna edici**, görünən boyut və uyğun mesafə."]}],"number":13,"title":"Açık hava reklamı","traps":["Dağıtımı **sadece belediyeler** etmir.","**Fotomontaj** açık hava malzemesi deyil. **Bilgilendirici** tabela tekniki deyil.","Dezavantaj: **genellikle akılda kalıcı deyil**.","Outdoor TV-də \"dikkat qısa qalır\", \"gerçeği yansıtma zorunluluğu yoktur\" **yanlışdır**.","**Delikli** lightbox türü deyil."]},{"blocks":[{"points":["**Webster**: **8** gereksinim sınıfı (yemek-içmek, refah, karşı cinsi etkileme, korkudan uzak, üstün, toplumsal olma…).","**Maslow**: **fizyolojik → güvenlik → üyelik ve sevgi → saygınlık → öz gerçekleştirme**.","Uyarıcılar: **ussal, duygusal, tehdit\/korku verici, güldürü, çağrı**.","**Gestalt**: Wertheimer, Koffka, Köhler (+ Kant, Mach). Bütün və örgütə diqqət; mesaj **kolay algılanır** biçimdə.","Kurumsal kimlik: logo, kartvizit, diplomat zarf, antetli, dosya, broşür, ambalaj, etiket, fatura, adisyon."]},{"heading":"Ürünlər","points":["Həm açıq həm iç mekan: billboard, raket, **lightbox**, silindir, parapet, mesh, pole banner, transit.","**Alternatif reklamcılık** = gerilla mecra; iç mekan: kaldırım, duvar, tavan, **zemin** uygulaması.","**Onboard**: uçak içi — program, dergi, koltuk arkası, tepsi masası, **baş üstü saklama kutusu**, uçuş görevlisi.","**One way vision**: camekan, **delikli, yapışkanlı folyo**.","**Pop up stand**: örümcek, centro, roll up, X banner, quick banner, broşürlük, **alarm kılıfları** (mağaza girişi).","**Kiosk**: etkileşimli bilgisayar; iç, dış, totem, self check-in, ateş ölçer\/dezenfektan.","**POP**: satın alma kararı verilən yer. 3 açar: **mağaza içi etkileşim, potansiyel müşteri, satın alma kararı**. Süre: **geçici, yarı kalıcı, kalıcı**.","POP ürünləri: shelf talker, wobbler, raf kart, raf şeridi, **dönkart** (rafdan bağımsız), foreks, roll up, **dump bin**.","**Promosyon**: logolu ürün (ajanda, kalem, termos…); **sürdürülebilirlik** → **bez çanta**."]}],"number":14,"title":"İç mekan reklamı","traps":["**Dokunsal** uyarıcı deyil. **Bloknot** kurumsal kimlik deyil (promosyondur).","**Termos** kırtasiye deyil. **Uçak** kiosk alanı deyil.","**Raf kart** həm açıq həm iç mekan ürünü deyil (POP-dur).","Dump bin-də **televizyon** sergilenmez."]}]},"Tasarım Okumaları":{"intro":{"heading":"Fənnin xəritəsi","points":["**1–2**: tarix. Antik dövrdən akımlara, sonra **Bauhaus**.","**3–4**: görsel dil. Öğeler, ilkeler, **kompozisyon**.","**5**: **tasarım temelli araştırma** (təhsil sahəsi, döngüsel).","**6–7**: yaratıcılıq, yöntemlər, **Altı Şapka**, **tasarım düşüncesi**.","**8–9**: yaratıcı stratejilər, **tasarım estetiği**. **10–11**: texnologiya, **XR**, dijital çağ.","**12–14**: **sürdürülebilirlik**, **inovasyon**, **etkileşim tasarımı** (UI\/UX)."]},"quick":["Tekhne → işlevsel şey · Vasari → Disegno · tabure → Antik Mısır · Barok → elips","Morris → Arts & Crafts · Gaudi → Art Nouveau · Rodchenko → Konstrüktivizm · De Stijl → doğasız soyut","Bauhaus: Weimar → Chicago · Gropius-Meyer-Mies · Nazi bağladı · Breuer Wassily, Mies Brno, Brandt çaydanlık","Şekil 2D, biçim 3D · nitelik kontrastı → kroma · kırık renk → hər rənglə uyum, arka planda","Kantar → iki kütlə · örüntü → soyut · solucan bakışı → alttan · atmosferik → uzaq soyuq və silik","TTA: 1960-lar, Allan Collins, eğitim bilimleri, çox uzun sürür","Şapka: Mavi düzen · Beyaz bilgi · Yeşil yaratıcı · Kırmızı duygu · Sarı avantaj · Siyah tehlike","Moggridge → Etkileşim · Tim Brown → pazar fırsatı · Aspen · Iraksak çox cavab, Yakınsak tək cavab","Slavin → Eleştirel · Yansıtıcı → başqalarının deneyimi · Monet → Bükme+Uyarlama · Guernica → Parçalama · Basitleştirme strateji deyil","Altamira M.Ö. 22000 · Göbeklitepe M.Ö. 12000, hayvan figürü · Platon → kopya · Aristo → mimesis · Gazali → cemal · Hegel → sembolik","Photoshop piksel · Illustrator vektör · InDesign 1999 mizanpaj · Dall-E difüzyon · ekransız → kör tablet · Unity → VR mekân","VR yalıtır · AR bindirir · MR ikisi, orta · 3B baskı = Hızlı Prototipleme · Üretken Estetik 1965 sonrası · Doğrusal sistem mo-cap deyil","Stockholm 1972 · tanım 1987 · 17 hedef · Biyomimikri → doğa taklidi · İnovasyon → ekonomi, dönüştürme · HCI · Moggridge 5 boyut · Nielsen 1994"],"units":[{"blocks":[{"heading":"Anlayışlar","points":["Tasarım tərifləri: zihinde canlandırılan biçim, ilk taslak, dizayn, bilinç içeriği.","**Tekhne**: bir amaç gözeterek ortaya **işlevsel bir şey koyma**.","Tekhne: mimarlık, marangozluk, siyaset, tıp. **Öğretmenlik** tekhne deyil.","**Vasari** tasarımı **Disegno** ilə izah edir."]},{"heading":"Dövrlər","points":["İlk oturma mobilyası, **tabure**: **Antik Mısır**.","Antik Yunan: heykel kimi, stereometrik, tapınaq **megaron**dan, sütun üstündə alınlıklı çatı.","**Barok** mimaridə **elips**.","**Rococo**: iç mekân tasarımı, **Barok və Rocaille**dən təsirlənib.","Endüstrileşmə yeniliyi: **demir** istifadəsi."]},{"heading":"Akımlar (Endüstri Devrimi sonrası)","points":["**Arts & Crafts**: 19. əsr sonu, **William Morris**. İlham: **Orta Çağ əsərləri və doğa**.","**John Ruskin**: \"Sadece **estetik açıdan iyi** tasarlanmış nesneler değerli ve kullanışlı olabilir.\"","**Art Nouveau**: ən ünlü təmsilçi **Antoni Gaudi**.","**De Stijl**: **doğadan yola çıkmayan soyutlamalar**. Doğadan ilham **yoxdur**.","De Stijl üzvləri: Theo Van Doesburg, Piet Mondrian, Bart Van der Leck, Georges Vantongerloo.","**Konstrüktivizm**: **Alexandr Rodchenko**. Sanat matematiğin koludur, yaşamda işlevi olmalıdır."]}],"number":1,"title":"Tasarım tarixi və akımlar","traps":["**Teknik çizim** tasarımın tərifi deyil.","**Yüksek pencereler** Antik Yunan mimarisinin xüsusiyyəti deyil.","**Rokoko** Endüstri Devrimi sonrası akım deyil.","**Jan Van Eyck** De Stijl üzvü deyil.","\"Sanat güzelin yansıtılmasıdır\" Rodchenkoya aid **deyil**."]},{"blocks":[{"points":["Kaynaklar: Arts and Crafts, Alman İş Derneği, Van der Velde-nin Weimar okulu, Gropius-un proqramı.","İlk şəhər: **Weimar**. Yeni Bauhaus: **Chicago**.","Rəhbər sırası: **Gropius → Meyer → Mies van der Rohe**.","İlk dəvət edilən İsveçrəli ressam-ekspresyonist: **Itten**.","Bağlanma səbəbi: **Nazi rejimi**.","Yaratdığı akım: **İşlevselcilik**. \"Çağdaş tasarımın beşiği\" deyən: **Adobe**.","İlkələr: ergonomik, şəhər həyatına uyğun, asimetrik, texnoloji. Resimsiz duvar, çox cam, çox metal, mat camlı lamba.","İşlevselcilik: saf geometrik form, tək materialdan böyük düzlem, bol cam, işlevsiz detay yox.","Töhfələr: yeni estetika, bireysel özgürlük, kollektif yaratıcılıq, **disiplinlerarası** yanaşma."]},{"heading":"Adlar","points":["**Marcel Breuer**: **Wassily** koltuğu.","**Mies van der Rohe**: **Brno** koltuğu.","**Anni Albers**: tekstil. **Marianne Brandt**: metal atölyesi, ikonik **çaydanlık**.","Ünlü öğrencilər: Gunta Stölzl, Marianne Brandt, Josef Hartwig, Josef Albers."]}],"number":2,"title":"Bauhaus","traps":["**İkinci Dünya Savaşı** Bauhaus-un kaynağı deyil.","**Süslü olması** Bauhaus ilkəsi deyil. **Bol süsleme** işlevselciliyə görə yanlışdır.","**Kuş ve çiçek desenli duvar kâğıdı** Bauhaus stili deyil.","**Itten koltuğu** yoxdur (Brno, Cesca, Wassily, Albers sehpaları var).","**Tek disipline odaklanma** töhfə deyil.","Bauhaus təsiri **Kulinari**də görülmür.","**William Morris** Bauhaus öğrencisi deyil."]},{"blocks":[{"heading":"Öğeler","points":["Görsel öğeler: çizgi, renk, **değer**, biçim.","Çizginin fiziki xüsusiyyətləri: yön, tür, konum, karakter.","**Şekil iki boyutlu**, **biçim üç boyutlu**.","**Değer**: rəngin **açık və ya koyu** olması.","Doku: soyut, gerçek, icat edilmiş, taklit.","Kırık (toprak) renk: **her renkle uyum** sağlayır.","Renk çarkında yan-yana: **Analog**.","Kontrast: açık-koyu, eş zamanlı, nitelik, sıcak-soğuk. **Nitelik kontrastı** → **kroma**."]},{"heading":"İlkeler","points":["Sıra: **vurgu, oran, hareket, uyum, tekrar, ritim, denge, kontrast**.","Çeşitlilik vasitəsi: **kontrast və detaylandırma**. Önəmi: **özgün və ilginç** edir.","Uyum vasitəsi: **tekrar, ritim, tamamlama, görsel ilişkilendirme**.","Görsel ilişkilendirme: **örtüşme, şeffaflık, geçişme, ortak kenar paylaşma**.","Birinə diqqət çəkən xüsusiyyət vermək: **Vurgu\/baskınlık**.","Yalnız ən lazımlı öğe: **Sadeleştirme**.","Geştalt: **şekil-zemin ilişkisi**. Gruplama: ebat, konum, biçim, uzamsal yönelim benzerliği."]},{"heading":"Uzam","points":["Dekoratif uzamda **derinlik kaygısı yoxdur**. Plastik uzam: **üç boyutlu yanılsama**.","**Derin uzam**: bakışı **uzaqlara** yönəldir. Gerçek uzamda 3D nəsnələr var."]}],"number":3,"title":"Tasarım öğeleri və ilkeleri","traps":["**Ritim** görsel öğe deyil.","**Karışık doku** doku çeşidi deyil.","**Hava kontrastı** yanlışdır.","\"Derin uzam izleyici bakışını ön planda tutar\" **yanlışdır**.","**Duruş benzerliği** gruplama benzerliyi deyil.","**Güzelliği** çizginin fiziki xüsusiyyəti deyil."]},{"blocks":[{"points":["Tərif: **belli ilişkiler içinde** bir araya gələn parçaların düzəni.","Ən önəmli amaç: **mesajın net iletilmesi**.","Estetik güzəllik: **parçalar arası iletişim və uyum**.","Bütüncül tasarım: **konu, içerik, form**.","Növlər: açık, kapalı, üç boyutlu, simetrik.","**Kantar**: iki fərqli kütləni zıtlaşdıraraq dengeler.","Soyuta ən yaxın: **örüntü kompozisyonu**.","Altın dikdörtgendə vurgu: **diyagonallerin kesişme noktaları**.","Ən alçaqdan yuxarı baxış: **solucan bakışı**.","Duyğusal narahat edən: **doğal olmayan düzen**.","Vurgu ən çox **zıtlık**la bağlıdır.","Asimetrik: dinamik, ilgi çəkici, ilgini canlı saxlayır, basit deyil."]},{"heading":"Renk və perspektif","points":["Kırık renk: **arka planda böyük miqdarda**. Uyum səbəbi: **tüm renklerin karışımı** olması.","**Atmosferik (hava) perspektif**: uzaq → soyuq rəng, silik sınır, az detay, açıq və yaxın dəyərlər. Yaxın → isti, detallı.","Değer: degrade kademeli dəyişir, bənzər dəyərlər qrup kimi görünür, məsafə və vurgu verir."]}],"number":4,"title":"Kompozisyon","traps":["**Kıvrımlı dağınık kitle dengeli** kompozisyon türü deyil.","**Viyadük** 15 arketipdə yoxdur (ters kantar, U, tünel, S var).","\"Benzer karakterli çizgiler yan yana farklı değerler oluşturur\" **yanlışdır**.","Asimetrik kompozisyon **hemen anlaşılmaz**.","Atmosferik perspektifdə **detaylar abartılmır**."]},{"blocks":[{"points":["Kökü: **1960-lar**. Kuramçı: **Allan Collins**.","Çox katılımlı, **döngüsel**, karma yöntemli. Probleme yaratıcı, yansıtıcı həll.","Uğur ölçüsü: süreç, tasarı, karar, analiz, yenidən tasarım **döngüsel tekrarlanır**.","Wolcott: **teori odaklı, iş birlikçi, pratik, yinelemeli**.","Wolcott tövsiyələri: fərqli ekip, yöntem seçmək, plan + dəyişikliyə açıq olmaq, paydaşları daxil etmək.","Yöntemlər: tasarım deneyleri, tasarım araştırması, geliştirme araştırması, biçimlendirici araştırma.","Aşamalar: analiz-keşif, tasarım-inşa, değerlendirme-yansıtma, uygulama-yayılma.","Eylem araştırmasından fərqi: **tasarım sorunlarına odaklanıb yenilik üretmek**.","Əsas sahə: **eğitim bilimleri**. Ən az: **ziraat**.","Katılımçılar: akademisyen, tasarımcı, öğretmen, alan uzmanı.","Zorluk: **çox uzun sürmesi**, çox veri, analiz yükü, mali yetersizlik.","Az tercih edilən veri yolu: **tıbbi laboratuvar deneyleri**.","Dəyişənlər: ortam, öğrenenlerin doğası, mali gereklilikler, uygulama çizelgesi.","Yol: ilk müdahale → test → düzeltme → yenidən test → ən az hatada **rapor**."]}],"number":5,"title":"Tasarım temelli araştırma","traps":["\"**Sadece bireysel**\" araştırma deyil.","**A\/r\/tografi** tasarım temelli yöntem deyil.","**Kısa süreli** Wolcott xüsusiyyəti deyil.","**Toplama ve sınıflandırma** aşama deyil.","\"Sadece teorik, uygulamasız\" Wolcott tövsiyəsi **deyil**.","**Araştırma konusunun bulunması** zorluq deyil.","**Sistemsiz** deyil. **Pilotlar** katılımçı deyil.","\"İlk tasarımdan sonra sonlandırmaq\" yol **deyil**.","\"Sonuçların nasıl sunulacağı\" dəyişən **deyil**."]},{"blocks":[{"heading":"Yaratıcılıq","points":["Yaratıcılıq **insana ait bir yetidir**.","Üç değişken: **çevresel, bilişsel, kişisel**.","Bilişsel değişkenler: **zekâ, bilgi, teknik yetenekler, özel yetenekler**.","Amacı özündən kənarda, maddi və çıxarcı: **sıradan normal ve bağımlı kişi**.","Olumsuz örgütsel: otoriter yönetim, baskı, yersiz eleştiri, ciddilik tutkusu.","Olumsuz kişisel: saplantı, tembellik, kararsızlık, **özgüven eksikliği**.","Olumsuz toplumsal: aile, eğitim, medya, moral değerler."]},{"heading":"Tasarım süreci","points":["Bilgi derleme: toplama, sınıflama, kaydetme, özetleme.","Tasarım odaklı düşünme: **Empati → Tanımlama → Planlama → Prototip → Test et → Değerlendir**.","Problemlə yox, **gözlemle** başlayır.","Yöntemler: analojik, metaforik, tümevarım, diyalektik (karşılaştırmalı).","Aşamalar: araştırma, çözümleme, bireşim, geliştirme.","Veri kaynakları: uzmanlar, başarılı yapıtlar, tasarımcının birikimi, kitaplar."]},{"heading":"Altı Şapka (Tasvir Edici Yöntem)","points":["**Mavi**: analiz, karar, süreci düzenlemə.","**Beyaz**: kesin bilgi, tarafsızlık.","**Yeşil**: yaratıcı, yeni fikirlər.","**Kırmızı**: məntiqdən çıxıb **duygular**.","**Sarı**: fırsatlar, avantajlar.","**Siyah**: olumsuz, tehlikeli yanlar."]}],"number":6,"title":"Yaratıcılıq və tasarım yöntemleri","traps":["**Geliştirme** bilgi derleme işlemi deyil.","**Sezgisel yaklaşım ve motivasyon** olumsuz örgütsel etki deyil.","**Özgüven** olumsuz kişisel etken deyil. **Öz-saygı\/özgüven** olumsuz toplumsal etki deyil.","**Lavi Yöntemi** tasarım yöntemi deyil.","**Buluşturma** tasarım aşaması deyil.","**Tahmin ve varsayımsal yöntem** veri kaynağı deyil."]},{"blocks":[{"points":["**Tasarım Düşüncesi**: tasarım kapsamı xaricindəki sorunlara tasarım yöntemlərini tətbiq etmək.","Tasarımcılar yetkinliklərini **tasarım düşüncesi** yelpazesində genişləndirir.","Altıgen diyagram addımları: empati kurma, tanımlama, düşünme, prototip.","\"Tasarım\" Türkcə: plan, ilk taslak, zihinsel temsil, zihindeki canlandırma.","Grafik tasarım ayrı zanaat: **II. Dünya Savaşı sonrası**.","Yıllıq konferans (Steinem, Rauschenberg, John Cage, Sontag): **Aspen Konferansı**.","**Iraksak düşünme**: çoxlu, alternativ cavablar. **Yakınsak düşünme**: tək ən doğru cavab.","**İnsan Odaklı** yanaşma: insanı mərkəzə qoyur, psikososyal və fiziki veri.","Kalıcı izlər, \"anlamlandırma\": **deneyimler**."]},{"heading":"Geriye doğru tasarım","points":["Amaca yönelik **iş analizi**. Ardıcıl planlamadan **öğretim programı** çıxır.","Aşamalar: **istenen sonuçları tanımla → veri toplama araçlarına karar ver → tasarımı planla**."]},{"heading":"Adlar","points":["**C. West Churchman**: tasarım hamı tərəfindən, hər yerdə tətbiq olunur.","**Bill Moggridge**: \"**Etkileşim Tasarımcıları**\" terminini ilk işlədən.","**Tim Brown**: tasarım düşüncesi = insan ehtiyacını iş strategiyası ilə eşləyən disiplin və pazar fırsatı.","**Christopher Alexander**: problemi kiçik problemlərə böl. Tasarım **mistik və sezgisel deyil**.","**Rowland** 4 yön: amaç\/hedef, digər süreçlərlə ilişki, təsir edən faktorlar, sürecin doğası."]}],"number":7,"title":"Tasarım düşüncesi","traps":["**Ara verme** altıgen diyagram addımı deyil.","**Aktarım** \"tasarım\"ın Türkcə qarşılığı deyil.","**Tasarım eğitiminin tarihi** Rowlandın 4 yönündən deyil."]},{"blocks":[{"heading":"Biliş və motivasyon","points":["**Biliş**: zihinsel eylem, bilgiyi elde etme, düşünce və deneyim yoluyla anlama süreci və duyu. Duyarlılık, algı, imgeleme, anımsama, problem çözme daxildir.","Düşünmenin ən təməl xüsusiyyəti: **eylem içermemesi**, harekətə keçmədən əvvəl edilir.","**Motivasyon** (isteklendirme\/güdüleme): hedefe yönelik davranışları **başlatan, yönlendiren, sürdüren** süreç. Biyolojik, duygusal, sosyal, bilişsel güclər.","**İçsel**: ödülsüz, içdən gələn. **Dışsal**: para, ün, övgü.","Artırma yolları: hedef belirleme, ilerlemeyi gözden geçirme, sevdiyin işlər, sosyal destek, pozitif çevre, egzersiz, ödüller.","Uğursuzluqda problemi bir müddət kənara qoy: **kuluçka dönemi**ndə bilinçaltı həll çıxarır.","**Olgu**: hamı üçün eyni, kanıtlanabilir, bilimsel bilgi. **Kavram**: sinfi bütünüylə temsil eden genelleştirilmiş anlam. **Model**: taktik, teknik, strateji ilkelerinin sistemi."]},{"heading":"Mantıksal akıl yürütme modelleri","points":["**Bütüncül**: kavramları temel alır, **kavram\/zihin haritası**.","**Metabilişsel**: öz öyrənmə yollarının fərqində olmaq, ən yaxşı yolu tapmaq.","**Eleştirel**: **Slavin (2013)**, \"ne yapılacağı ve neye inanılacağı hakkında rasyonel kararlar verebilme meziyeti\".","**Analitik**: parçaları analiz edir, **tümden gelim** ilə alt konulara ayırır.","**Yansıtıcı**: həm özünün, həm **başkalarının deneyimleri** üzərində düşünmə.","**Yaratıcı**: yeni, orijinal, özgün (**sentez düzeyi**), ayrıştırıcı, alternatifli.","**Üstünoğlu (2006)**: **üst düzey düşünme** = eleştirel, yaratıcı, analitik, yansıtıcı, problem çözme."]},{"heading":"Yaratıcı düşünməni geliştirən yollar","points":["**Evrim**: həll olunmuş sorun daha yaxşı həll oluna bilər.","**Sentez**: iki və daha çox fərqli şeyi birləşdirib yeni ürün.","**Devrim**: köhnəni geliştirmək yox, **tamamilə fərqli işlevli** yeni ürün.","**Yeniden uygulama**: alışılmışın dışında, fərqli yol\/amaçla istifadə.","**Yön değiştirme**: bakış açısını dəyişib bir açıdan digərinə keçid.","**Iraksak düşünme**: çoxlu, kanıtlana bilən cavab, anlamlı suallar."]},{"heading":"Yaratıcı stratejiler","points":["**Bükme (çarpıtma)**: olgunun orijinal halı **biçimini itirəcək qədər** dəyişir.","**Parçalama**: bütün parçalanır, parçalardan **yeni bütün** qurulur.","**Harmanlama**: fərqli nəsnələr yeni biçim və yapıda birləşir.","Monet, **Rouen Katedrali** seriyası → **Bükme ve Uyarlama**. Newman **Kırık Obelisk**, Picasso **Guernica** → **Parçalama**.","Teknikalar: birleştirme, uyarlama, ikame, büyütme\/küçültme, **temellük** (kendine mal etme), yeniden düzenleme."]}],"number":8,"title":"Yaratıcı stratejilər və düşünmə","traps":["**Basitleştirme** yaratıcı strateji deyil.","**Teknik illüstrasyonlar** düşünce yöntemi deyil.","\"**Beklemek + ertelemek**\" motivasyon artırma yolu deyil.","Düşünmə **eylem içermir** — yanlışdır, eylemdən əvvəl edilir.","Monet → **Çekme ve İtme** deyil, **Bükme ve Uyarlama**."]},{"blocks":[{"heading":"Anlayışlar","points":["**Tasarım estetiği**: tasarımın **hoşa giden biçimlere** dönüşməsi, sanata evrilən yönü, ürünün güzəlliyi. Toplum, inanç, gelenek, ananeyə görə biçimlənir.","Tasarımın tarixi süreci: **insanın bilinçli çabaları** ilə başlayır.","İlk tasarım ehtiyacı: **M.Ö. 22000**, İspaniyada **Altamira** mağarası. İlk ürün: **mağara duvar resimleri**.","**Kültür**: nəsildən nəslə ötürülən maddi və manevi dəyərlərin tümü, \"bütün bir toplum için yaşam biçimi\".","Güzellik və çirkinlik **görecelidir**, kültürə görə dəyişir.","İnsan əvvəl **biçimə**, sonra **işlevə**, ən son **renk və dış çizgilərə** baxır.","Tasarım işlevini yerinə yetirəndən sonra **sanat** sayılır. İşlev olmadan tasarım **sadəcə biçimdir**."]},{"heading":"Dövrlər","points":["**Göbeklitepe** (M.Ö. 12000, Şanlıurfa): piramitlərdən **7500 il** əvvəl, **ilk ibadet merkezi**. Sanat əsərindən çox **ihtiyaç ürünü**. T taşlarında çoxu **hayvan figürleri**.","**Mezopotamya** (M.Ö. 4000): \"nehirler arası\", öndə **Sümer**. Tarım aletleri və pişmiş tuğla.","**Hititlər** (M.Ö. 1600): **hiyeroglif**, **tunç** əsərlər.","**Antik Mısır** (M.Ö. 3000): fiziki gözəllik; inanç ritüelləri mimari, heykel, resmə; piramit, sfenks.","**Antik Yunan** (M.Ö. 8. yy): zirvə **Büyük İskender**. Ən çox **Tanrı heykelleri**, heykel okulları.","**Sanayi Devrimi**: 1760–1830, **İngiltere**. Əvvəl **üretim fazlası** yox idi. Seri üretim → **bütün ürünlər eyni tasarım və estetikdə**."]},{"heading":"Filosoflar","points":["**Platon** (Devlet): sanat gerçekliği temsil edə bilməz, **kopyadır**. Sanatçı **Tanrının yaratıklarının kopyasını** yapar.","**Aristoteles**: **mimesis** = doğanın **mükəmməlliyi və yenidən biçimlənməsi**; riyazi fikir və simetriya.","**Gazali**: estetik = eşyanı güzəl edən düşüncəni **eşyanın içində** axtarmaq. **Cemal** = güzəl. \"Her varlık Allah'ı anıyorsa güzeldir.\"","**Kant** (Yargı Yetisinin Eleştirisi): güzəl sənət növlərini **ilk dəfə sınıflandırdı**. Güzəllik algısı **evrensel** ola bilər.","**Hegel**: **sembolizm, klasizm, romantizm**. Ən çox **sembolik sanat** üzərində durur."]}],"number":9,"title":"Tasarım estetiği","traps":["Tasarım estetiği \"**dikkat çekmek**\" və ya \"kaliteli ürün\" deyil, **hoşa giden biçimler**.","Göbeklitepe **sanat eseri deyil**, ihtiyaç ürünüdür.","**Lascaux** İspaniyada deyil; İspaniya mağarası **Altamira**.","\"Güzellik mütləqdir\" **yanlışdır**, görecelidir.","\"**Resim yapmak günahtır**\" İslam estetiğinin tərifi deyil."]},{"blocks":[{"heading":"Yazılım","points":["**Dijitalleşme**: 1900-lərin **son çeyreği**. Grafik tasarım **1960-lardan** dijitallaşır.","Sektör lideri: **Adobe**, ödənişli **Creative Cloud** üyeliyi.","**Photoshop**: **piksel tabanlı** görüntü\/fotoğraf işləmə. Çox vaxt **dijital mecra**.","**Illustrator**: **vektör**; ölçüləndə keyfiyyət itmir. İllüstrasyon, afiş, **tipografi**.","**InDesign**: ilk sürüm **1999**, **masaüstü yayıncılık və mizanpaj** (broşür, kitap, gazete).","**Premiere Pro**: video **və ses** düzenleme.","Basılı mecrada **vektörel** (InDesign, Illustrator) — çalışma alanı böyüyəndə **bozulma olmaz**.","**Procreate**: iOS Apple tablet, dijital çizim. Bənzəri: **SketchBook**. **Unity** → sanal gerçeklik mekân tasarımı.","**Dall-E**: metni görselə çevirir, **difüzyon** ilə; mövcud şəkilləri birləşdirmir."]},{"heading":"Donanım","points":["Ən çox istifadə olunan: **bilgisayar**. Yüksək kapasite (ekran kartı, işlemci, RAM) → 3D, video, **render**.","Tablet: iPad\/Samsung genel kullanıcı; **Wacom** profesyonel çizerlər.","Çizim tabletləri **ekranlı və ekransız** — iki qrup. Ekransız = **kör tablet**. Ölçü 5–27 inch.","Çizim kalemində ən belirleyici xüsusiyyət: **basınç hassasiyeti**."]},{"heading":"Mecralar və yönelimlər","points":["**Basılı**: kartvizit, branda, ambalaj, kitap kapağı, broşür, afiş (ofset\/dijital baskı).","**Dijital**: oyun, reklam, arayüz, **landing page**, e-yayıncılık, 3D yüzey.","Yapay zekâ: əsasən **fotoğraf işleme və akıllı tasarım**.","**Deneysel tasarım**: VR, AR, MR və **paralel gerçeklik**; həm 2D, həm 3D ortamlar."]}],"number":10,"title":"Tasarım teknolojileri","traps":["**Premiere Pro** piksel tabanlı görüntü işləmə deyil (video).","**Publisher** Adobe yazılımı deyil.","\"Ekranlı, ekransız və **yarı ekranlı**\" — yanlışdır, iki qrup var.","Illustrator-da **ses dosyası birleştirmek** olmur.","Deneysel tasarım \"**sadəcə yapay zeka**\" deyil.","**Bilgisayarın performansı** basılı tasarımdan əvvəl bilinməli husus deyil."]},{"blocks":[{"heading":"Dijitalleşme və sənət","points":["Dijitalleşmə tasarımı **üretim biçimi\/medyumu** və **hedef mecrası** baxımından dəyişib: kolay, düşük maliyetli, hızlı.","Sanayi Devrimi (18. yy) → **tüketim odaklı** toplum.","**Üretken Estetik** və **Yapay Sanat**: **1965 sonrası**.","**1968 ASCII Sanatı**, **1973 Robotik Sanat**; sonra Elektronik Sanat, Video Enstalasyon; 2000+ **Video Oyun Sanatı**.","Bilgisayar: yardımcı araçdan **ortak yaratıcıya**.","Eskiz: olgunlaşmamış fikri başqalarına və özünə **ifade etmek** üçün."]},{"heading":"XR və AI","points":["Grafik tabletlər əvvəl **el yazısı** üçün idi.","**XR (Genişletilmiş Gerçeklik)**: AR, VR, MR-ı əhatə edən **şemsiye terim**.","**VR**: istifadəçi **fiziki dünyadan yalıtılır** — AR və MR-dan əsas fərq.","**AR**: mobil ekranda görüntü fiziki dünya üzərinə **bindirilir**, yalıtma yoxdur.","**MR**: VR + AR **harmanı**; fiziki ortamla sayısal veri etkileşir; spektrumun **ortası**.","**AI**: öngörülebilir hedeflər üçün **mantıksal karar sistemi**."]},{"heading":"Baskı və veri alma","points":["Dijital baskı faydaları: **gerçek zamanlı prova**, esneklik, parlak renk, **talep edilen miktar**, geleneksel baskı ilə bağlantı, **değişken data**.","**3B Baskı = Hızlı Prototipleme**; katman-katman. Texnologiyalar: **FDM, SLA, SLS**. Modada: aksesuar, **prototipler ve araçlar**.","**Hareket yakalama (Mo-cap)**: tıp, animasyon, film. Sistemlər: pasif\/aktif optik, işaretsiz, inersiyal.","**Fotogrametri**: **2D görüntü dizisindən 3D** bilgi. **DICE**: Battlefield, Star Wars: Battlefront."]},{"heading":"Disiplinlər","points":["Grafik trendlər: tipografi, stock fotoğraf, **izometrik çizim**, Pop Art, soyut çizim.","**Endüstriyel Tasarım** (Amerika Endüstriyel Tasarımcılar Derneği): üretici və kullanıcının karşılıklı yararı üçün **işlev, değer, görünüm** optimizasiyası.","Moda temkinli idi: dijital **\"insan dokunuşu\"** verə bilmir. Moda CAD: Marvelous Designer, C-Design Fashion, CLO 3D, TUKA 3D.","Tasarımcı yetkinliyi: alət bilgisi yox, **problemi tasarımla həll etmə ustalığı** və paylaşma; trendləri izləmək."]}],"number":11,"title":"Dijital çağda tasarım","traps":["**Doğrusal Sistemler** hareket yakalama texnologiyası deyil.","**Yüksek maliyetler** dijital baskı faydası deyil.","**Adobe Premiere** moda CAD yazılımı deyil.","VR-da istifadəçi **sanal dünyadan** yox, **fiziki dünyadan** yalıtılır."]},{"blocks":[{"heading":"Kavram və tarix","points":["**Sürdürülebilirlik**: gələcək nəsillərin ehtiyacından ödün vermədən **bugünün ihtiyaçlarını** karşılamaq. **Yaşamı yöneten temel ilke**.","Daxildir: doğal kaynak, ekonomik kaynak, tüketim politikası, görsel kültür felsefesi, sosyal eşitlik.","Sürdürülebilir tasarım fikri, çevre hareketi: **1960**.","Farkındalık toplantıları: 5–16 Haziran **1972, Stockholm** (BM İnsan Çevresi Konferansı).","Tanım: **1987** (Brundtland, \"Ortak Geleceğimiz\").","**1992 Rio**: çevreye duyarlı politikalar. **2002 Johannesburg**: biyolojik çeşitlilik kaybını durdurmaq.","**17 hedef**: yoksullukla mücadele, sıfır açlık, sağlıklı yaşam, sorumlu üretim ve tüketim, toprak ve arazi yaşamını korumak və s."]},{"heading":"Biyomimikri və doğal çevre","points":["**Biyomimikri**: doğanın işleyişinin **taklidi**; həlləri teknik və mühendislik disiplinlərinə ötürmək.","İlk örnek: **ipek böceği** — amma **kötü örnek** (böcəklər haşlanır).","Spiral 6 addım: **Tanımlama, Çevirme, Gözleme, Soyutlama, Uygulama, Değerlendirme**. Doğa **ihtiyacı kadar enerji** üretir.","**Doğal çevre**: insan təsiri olmadan işləyən sistem. Doğal olmayan üretim çevre **deyil**."]},{"heading":"İlkeler, görsel tasarım, ambalaj","points":["6 kriter: doğal ortam\/hammadde, materyal işleme və enerji, parçaların üretimi, üretim-tüketim iletişimi, ürün kullanımı, **ürünün ömrü və geri dönüşümü**.","Görsel tasarımın əsas amacı: farkındalıq yaradıb toplumun **algılarını** dəyişmək.","Kriterlər: çevre dostu malzeme, geri dönüşümlü yüzey, sürdürülebilir baskı, **baskı yerinə dijital**.","Petrol → **naylon** (plastik) ambalaj; təbiətdə **500–1000 il** qalır. Sebzələr öz ambalajını üretir → **bitki kökenli** ambalaj.","**Aldığını yerine koyma ilkesi**: istifadə edilənin yerinə yenisini qoymaq. **Fosil kaynaklar** bu ilkəni pozur.","Asıl amaç: **daha düşük enerji, daha az atık**. Geri dönüşüm logosu: toplamak, geri dönüştürmək, geri dönüştürülmüşü satın almaq."]}],"number":12,"title":"Sürdürülebilir tasarım","traps":["**Makineleşme**, **işsizliği önleme** kalkınma hedefi deyil.","**Sürekli üretim** geri dönüşüm logosunda yoxdur.","\"**Ambalaj dayanıklı olmalıdır**\" sürdürülebilir ambalajın cavabı deyil.","Sürdürülebilir tasarım \"**hoşa giden biçimler**\" deyil — bu estetikdir."]},{"blocks":[{"heading":"İnovasyon","points":["21. yy-da **finansal alanda** baskın termin; 1960 sonrası zənginləşib, **kırılmaya dayalı**.","Var olanın güncel dəyərlərə görə **dönüştürülmesi və geliştirilmesi**. **Yoktan var etme \/ icat kaygısı yoxdur**.","Türkçe literatürdə **ekonomi** ilə; yönetim, ürün-hizmet, kâr-zarar, satış ilə anılır.","**Er və Er (2003)**: tasarım = teknoloji və bilginin ürünə çevrildiyi **yenilikçi** süreç. Tasarım **aktif, sürekli kendini yenileyen** süreçdir."]},{"heading":"Aşamalar","points":["**Süreç aşaması**: müşteri ehtiyac və sorunları, yaratıcı fikirlər, **disiplinlerarası**; neyin nasıl yapılacağı.","Strategiya üçün lazım: **yüksek bilgi, farklı bakış açısı, keşfetmek**, sosyal gözlem.","**Sonuç aşaması**: stratejilər hədəfə çatdımı — dəyərləndirmə.","Tasarıma önəmin artması: **müşteri odaklı** olmaq. Verimlilik: **yetkin bilgi və odaklanma**.","**Multidisipliner (çok disiplinlilik)**: fərqli sahə uzmanları **öz sərhədlərini aşmadan** tək çözüm."]},{"heading":"Düşünme metotları","points":["**Sezgisel**: riyazi veri olmadan **gözlemle**. **Analitik**: katı kural, mantıksal sonuç.","**Iraksak**: limitsiz alternativ çözüm. **Yakınsak**: bilgiyə dayalı, **doğruya en yakın**.","**Soyut**: keşif, zihinsel eylem. **İmgesel**: kelimeləri **imgelərə** çevirir.","**Hayal gücü**: zihinsel imgeler, alakasız parçalar arasında ilişki.","**Çağrışımsal**: kavram başqa kavramlarla **birlikte xatırlanır**; öznel."]},{"heading":"Başarı unsurları","points":["Yaratıcılık, özgünlük, kalıcılık, estetik, uyum.","**Mevcut durumu kabul etməmək**, tanımlama (hedef kitle), multidisipliner **bilgi**, **basit ama odaklı**.","**Olmayanı tasarlama kaygısından uzak** olmaq. Bu kaygı **farklı bakış açılarıyla** baxmağı sınırlayır."]}],"number":13,"title":"Tasarım və inovasyon","traps":["**Olmayanı tasarlama kaygısı** başarı unsuru deyil.","**Mantıksal + soyut** düşünmə bir arada istifadə olunan cüt deyil.","**İcat elde etme kaygısı** və **kâr odaklılıq** tasarıma önəmin səbəbi deyil.","İnovasyon Türkcədə **moda, sanayi** ilə yox, **ekonomi** ilə bağdaşır."]},{"blocks":[{"heading":"Anlayışlar","points":["**Etki**: birinin başqa varlıqda yaratdığı dəyişim.","**Etkileşim**: ən az iki nəsnə\/insan bir-birini **geçici və ya kalıcı** etkiləyir. TDK: değiştirme, yeni bir form haline getirme.","**HCI** = Human-Computer Interaction = **İnsan-Bilgisayar Etkileşimi**.","Web və İnternet fərqlidir. Web (WWW): açılan **sayfalar\/siteler**.","**Web 1.0**: **tek taraflı**, istifadəçi pasif, okuma-araştırma. **Web 2.0**: **kullanıcı merkezli**, çox insan içerik üretir. **Web 3.0**: yayılmaq üçün hələ vaxt lazımdır."]},{"heading":"Etkileşim tasarımı (IxD)","points":["**IxD**: kullanıcılar və ürünlər arasındakı etkileşimin dizaynı; interaktif dijital ürün, ortam, sistem, hizmet.","Amaç: istifadəçinin istək və ehtiyaclarına **ən yaxşı şəkildə** çatmaq.","**Moggridge (2007)**, \"Designing Interactions\" — **5 boyut**: **Kelimeler, Görsel Temsiller, Fiziksel nesneler\/uzay-mekân, Zaman, Davranış**.","Testdə \"Etkileşim Tasarımı-nı doğru anladan\" cavab: \"en az iki nesne\/insan bir-birini geçici\/kalıcı etkiləyir\"."]},{"heading":"UI və UX","points":["**UI** (User Interface): ekran, düğme, geçiş, simge, görsel öğeler. **Yalnız dijital** ürünlər.","**UX** (User Experience): **hiss daxil** bütün etkileşim süreci; **IxD-ni də əhatə edir**, dijital olmayanlara da tətbiq olunur.","UX tasarımcısı: kullanılabilir, eğlenceli, **erişilebilir**; persona, analiz, test.","UI tasarımcısı: grafik kısımlar, menülər, renk paleti, yazı tipi, geliştiricilərlə iş.","UI-nin ən önəmli rolü: istifadəçinin **dış yardıma ihtiyaç duymasını önlemek**.","**Jakob Nielsen (1994)**: \"Etkili Arayüz Tasarımında **10 Yöntem**\". **Sistem durumunun görünürlüğü** → Netflix növbəti bölüm geri sayımı."]}],"number":14,"title":"Etkileşim tasarımı","traps":["**Renk** və **Donanım** 5 boyutdan deyil.","**Logo tasarımı** UI tasarımcısının birincil görevi deyil.","**Düğme tasarımı** UX deyil, UI görevidir.","Web 1.0-da bilgi akışı **çift taraflı** deyil."]}]},"Web Tasarımının Temelleri":{"intro":{"heading":"Əsas açar: kim nə edir?","points":["**HTML**: sayfanın **yapısı** (iskelet, anlam).","**CSS**: sayfanın **görselliği** (düzen, estetik, sunum).","**UI\/UX**: istifadəçiyə bilgiyə **hızlı, kolay, anlaşılır** erişim.","Ön yüz (front-end): **HTML, CSS və JavaScript**."]},"quick":["Berners-Lee → WWW · W3C → standart · DNS → IP · HTTPS → şifreli · POP3 → endirib silir","İlk addım → hedef kitle · psikografik → yaşam tarzı · wireframe → düşük sadakatli iskelet","Değil: Tutarlılık (Gestalt) · Filtreleme (Nielsen) · Estetiklik (WCAG) · Kod yazma (yolculuk)","50–75 karakter · sans-serif · yaşıl → huzur · Mobile First → kiçikdən böyüyə","<!DOCTYPE html> · <link> → CSS · <title> · <ul> · <tbody> · <th> · colspan · action · required","<main> · <nav> · <article> · <fieldset> – <legend> · alt","Seçici – Özellik – Değer · class → nöqtə · padding içdə, margin çöldə · border-collapse","Flexbox → tek boyut · justify-content · order · flex-grow · fr → esnek pay · @media · transition","=== → tip + dəyər · let\/const → blok · alert \/ confirm → onay \/ prompt → veri · onclick · return false","DOM → ağac · getElementById → tək öğe · querySelectorAll → NodeList · bubbling ↑ · stopPropagation · once: true","Bootstrap → Twitter · 12 sütun · container-fluid → tam · xxl ≥1400px · table-striped · needs-validation · $(\"#id\") · .append()","SEO: sayfa içi (meta) · sayfa dışı (backlink, sosyal) · teknik (URL, site haritası, mobil) · LCP < 2,5 s · SSL\/TLS","WordPress → blog · Moodle → LMS · Shopify → e-ticaret · Wix → bulut · RunwayML → video · Wireframe → Mockup → Prototip"],"units":[{"blocks":[{"heading":"Tarix","points":["**ARPANET** məqsədi: **güvenli bilgi paylaşımı**.","WWW-ni yaradan: **Tim Berners-Lee**.","Web standartlarını təyin edən: **W3C**."]},{"heading":"Protokollar","points":["**DNS**: alan adını **IP adresinə** çevirir.","**HTTPS**: **şifreli** iletişim (HTTP-dən əsas fərq).","**POP3**: e-poçtu endirir və çox vaxt **sunucudan silir**.","İstemci–sunucu: istemcinin işi **kaynak talep etmek**."]},{"heading":"HTML \/ CSS","points":["HTML: sayfanın **yapısını tanımlamak**. CSS: **görselliği düzenlemek**.","<body>: brauzerdə **birbaşa görünən** içerik.","Front-end: **HTML, CSS, JavaScript** (Node.js, MySQL, PHP deyil).","Erişilebilir tasarım: **hamı üçün** kapsayıcı, kullanılabilir içerik."]}],"number":1,"title":"İnternet və web","traps":["Erişilebilirlik \"sadece engelli bireyler üçün\" **deyil**, hamı üçündür.","POP3 e-poçtu sunucuda **saxlamır**, sinxron da işləmir.","\"HTTPS daha hızlıdır\" **yanlışdır**, fərq şifrələmədədir."]},{"blocks":[{"heading":"Hedef kitle","points":["Sürecin **ilk addımı**: **hedef kitleyi belirlemek**.","**Demografik**: məsələn **yaş** bilgisi.","**Psikografik**: yaşam tarzı, ilgi alanları, dəyərlər, motivasiya.","**A\/B testi**: iki versiya (düymə rəngi, düzən) təsadüfi qruplara göstərilib müqayisə edilir."]},{"heading":"Planlama","points":["**Bilgi mimarisi**: içeriyi **düzenlemek, kategorize etmek**, asan erişim.","**Wireframe**: görsel tasarımdan asılı olmayan, **iskelet**, **düşük sadakatli** çizim.","Kullanıcı yolculuğu: **Farkındalık, Araştırma, Karar, Deneyim**.","İçerik stratejisi: **dil və üslup, içerik türleri, SEO uyumlu, güncellenebilirlik**."]},{"heading":"Kullanılabilirlik","points":["**Kullanılabilirlik**: sayt nə qədər **kolay, hızlı, hatasız** istifadə olunur.","**Gestalt**: yakınlık, benzerlik, süreklilik, tamamlama.","**Nielsen** ilkələri: sistem durumunun görünürlüğü, sistem və real dünya uyumu, kullanıcı kontrolü, hata önleme.","Mobil uyum: responsive, dokunmatik ekran, mobil performans, minimalist tasarım."]}],"number":2,"title":"Tasarım süreci və kullanılabilirlik","traps":["**Yüksek kâr beklentisi** mobil uyumun maddəsi **deyil**.","**Kod yazma** kullanıcı yolculuğu aşaması **deyil**.","**Maliyet analizi** içerik stratejisi başlığı **deyil**.","**Tutarlılık** Gestalt ilkəsi **deyil**.","**Filtreleme** Nielsen ilkəsi **deyil**.","Hobilər, marka algısı demografik **deyil** (yaş demografikdir)."]},{"blocks":[{"heading":"UI","points":["UI məqsədi: bilgiyə **hızlı, kolay, anlaşılır** erişim.","UI ögesi: **menü butonları və ikonlar**.","**IxD** nümunəsi: basılan düymənin rəngi dəyişir, ilerleme çubuğu, form hata mesajı."]},{"heading":"Tipografi və rəng","points":["Sətir uzunluğu: **50–75 karakter**.","**Sans-serif** dijital mühitdə okunabilirliyi artırır.","**Yaşıl → doğa və huzur**.","**White space**: vurğunu artırır, **karmaşayı azaldır**.","Grid: hizalama, düzən və denge, görsel hiyerarşi, estetik."]},{"heading":"Erişilebilirlik və cihazlar","points":["**WCAG**: algılanabilirlik, çalıştırılabilirlik, anlaşılabilirlik, sağlamlık.","Görselə açıqlama: **Alt Metin (Alt Text)**.","**Mobile First**: **kiçik ekrandan** başlayıb böyüyə doğru.","Tutarlılıq: marka rəngləri, oxşar navigasyon, eyni işli ikonlar, eyni font ailəsi."]}],"number":3,"title":"UI, tipografi, erişilebilirlik","traps":["\"Metnin anlaşılır olması\" IxD nümunəsi **deyil**.","**Estetiklik** WCAG ilkəsi **deyil**.","**Görsel metaforlar** grid üstünlüyü **deyil**.","\"Tamamilə fərqli arayüzlər\" tutarlılıq ilkəsi **deyil**.","Yanlış: 100–150 karakter, 10px ana metin, aşağı kontrast, serif kiçik puntoda daha oxunaqlı.","Yanlış rəng cütləri: mavi–tehlike, qırmızı–güven, qara–neşe, sarı–lüks."]},{"blocks":[{"points":["İlk sətir: **<!DOCTYPE html>**.","CSS faylı: **<link rel=\"stylesheet\" href=\"stil.css\">**.","Stil və script etiketləri: **<style type=\"text\/css\"> ve <script>**.","Sayfa başlığı: **<title>**. Başlıq səviyyələri: **<h1>–<h6>**.","Görsel: **<img>**. Sırasız liste: **<ul>**.","İstifadəçidən veri toplamaq: **<form>**.","Form elemanı: məntiqlə **<input>**, amma bankda cavab **<html>** kimi verilib (yəqin səhvdir).","**Semantik HTML**: etiketləri **yapı və anlamına** görə düzgün işlətmək.","**Responsive**: **fərqli cihazlarda** uyumlu görünüş."]}],"number":4,"title":"HTML əsasları","traps":["**<content>** HTML etiketi **deyil** (<header>, <footer>, <style>, <article> var).","<style> CSS faylı bağlamır, bunu **<link>** edir.","Responsive \"sadece mobil\" və ya \"sadece masaüstü\" **deyil**."]},{"blocks":[{"heading":"Tablo","points":["Gövdə: **<tbody>**. Başlıq hücrəsi: **<th>**.","Yatayda bir neçə sütun: **colspan**."]},{"heading":"Form","points":["Verinin göndəriləcəyi ünvan: **action**.","Yalnız rəqəm: **<input type=\"number\">**.","Boş qala bilməz: **required**.","Qruplama və ekran oxuyucu üçün: **<fieldset> – <legend>**."]},{"heading":"Semantik və erişilebilirlik","points":["Ana içerik: **<main>**. Naviqasiya bağlantıları: **<nav>**.","Müstəqil içerik, makale: **<article>**.","Görsel üçün alternativ mətn: **alt**.","**WCAG** → **erişilebilirlik**."]}],"number":5,"title":"Tablo, form, semantik etiketlər","traps":["**method** hədəf ünvanı təyin etmir, bu **action**-dır.","**rowspan** sətirləri birləşdirir, sütunlar üçün **colspan**.","**placeholder** boş qalmağı əngəlləmir, bu **required**-dir."]},{"blocks":[{"points":["CSS: HTML-in **görsel düzenini, estetiğini, sunumunu** təyin edir.","Ən çox tövsiyə olunan: **Harici CSS** (ayrı .css faylı, <link> ilə). Səbəb: **bakım kolaylığı, tutarlılık**.","Qayda 3 hissə: **Seçici – Özellik – Değer**.","p { color: blue; } içində **color** = **Özellik (Property)**.","Class seçici: **nöqtə (.)** ön eki, çox elementə eyni stil."]},{"heading":"Kutu modeli və mətn","points":["**Padding**: içerik ilə kenarlık arası (iç boşluk).","**Margin**: digər qutularla məsafə, **ən dış** qat.","**border-collapse**: qonşu hücrə kənarları **tək xətt** olur.","**text-transform**: mətni **BÖYÜK hərfə** çevirir.","**letter-spacing**: **hərflər arası** yatay boşluk.","**vw \/ vh**: ekran eni\/hündürlüyünə görə **orantılı** dəyişir."]}],"number":6,"title":"CSS əsasları","traps":["Sayfa içi və satır içi CSS ən çox tövsiyə olunan **deyil**.","Kimlik seçici **#** ön ekidir, class deyil.","Margin içerik–kenarlık arası **deyil**, bu padding-dir.","letter-spacing satır arası və ya kəlmə arası **deyil**.","vw\/vh sabit **deyil**, kök font ölçüsünə bağlı da **deyil**."]},{"blocks":[{"heading":"Flexbox","points":["**Tek boyutlu** düzənlər üçün.","Yatay hizalama: **justify-content**.","Görsel sıra: **order**.","Daha çox yer tutmaq: **flex-grow**."]},{"heading":"Grid","points":["Sütunlar: **grid-template-columns**.","repeat(3, 1fr) → **3 sütun, bərabər en**.","**fr** = **esnek pay**.","Boşluq: **grid-gap**.","2 sütuna yaymaq: **grid-column: span 2;**"]},{"heading":"Responsive","points":["Media query: **@media**.","Mobil öncelikli: **əvvəl mobil üçün CSS** yazmaq.","Kiçik keçid effektləri: **transition**."]}],"number":7,"title":"Flexbox, Grid, responsive","traps":["repeat(3, 1fr) **sətir** deyil, **sütun** yaradır.","fr piksel, yüzde, rem, em **deyil**.","align-items yatay hizalama **deyil**, bu justify-content-dir.","@responsive və @container media query **deyil**."]},{"blocks":[{"heading":"Rolu","points":["HTML **yapı**, CSS **görsellik**, JavaScript **etkileşim və hərəkət** verir: statik sayfa → **dinamik** uygulama.","**İstemci tarafında** işləyir: sunucuya yük salmadan **anında geri bildirim** (məs. form xətasını dərhal yoxlamaq).","Böyük layihələr üçün framework-lər: **React, Angular, Vue**."]},{"heading":"Değişken, veri tipi, operatör","points":["Değişken: **var, let, const**. let\/const **blok kapsamı**, var **işlev kapsamı**.","Veri tipləri: **sayı** (yaş), **string** (ad), **boolean** (keçdi\/kəsildi), **dizi** (dərslər, notlar), **nesne** (tələbənin bütün bilgisi).","Operatorlar: **aritmetik, atama, karşılaştırma, mantıksal** (&&, ||, !).","**===**: həm **dəyəri**, həm **veri tipini** yoxlayır."]},{"heading":"Etkileşim","points":["Düyməyə tıklama: **onclick** olayı.","**alert()** → bilgilendirme, **confirm()** → **onay**, **prompt()** → istifadəçidən **veri almaq**.","Form doğrulama: e-posta\/şifrə qaydaya uyğun deyilsə **return false;** → form **sunucuya göndərilmir**.","Nümunələr: adı alıb salamlamaq (string + DOM), iki ədədi toplayan hesap makinesi, e-posta yoxlayan form."]}],"number":8,"title":"JavaScript-ə giriş","traps":["**def** JavaScript-də değişken açar sözü **deyil** (var, let, const var).","**console.log()** uyarı kutusu **açmır**, konsola yazır; kutunu **alert()** açır.","**==** tipə baxmır, tip+dəyər üçün **===**.","prompt() onay almır (bu confirm()-dir), veri **alır**."]},{"blocks":[{"heading":"DOM","points":["**DOM = Document Object Model**: HTML belgesinin **nesne tabanlı ağaç** quruluşu, hər öğe bir **düğüm**.","Erişim: **getElementById** (**tək öğe**), getElementsByClassName, getElementsByTagName, **querySelector**, **querySelectorAll** (**NodeList**).","İçerik: **innerHTML** (HTML işlənir), **innerText \/ textContent** (yalnız mətn).","Stil: **style**, **classList** (add, **remove**, toggle). Öznitelik: **setAttribute**.","Yaratmaq\/silmək: **createElement, appendChild, insertBefore, remove, removeChild**."]},{"heading":"Olay türleri","points":["Fare: **click, dblclick, mouseover, mouseout**. Klavye: **keydown, keyup**.","Form: **input, change, submit** (form göndəriləndə **submit**).","Pencere: **load, resize, scroll**. Medya: **play, pause, ended**.","Həm click, həm dblclick varsa: **əvvəl click**, sonra dblclick."]},{"heading":"addEventListener və yayılım","points":["**addEventListener**: bir öğeyə **birdən çox dinləyici**, **removeEventListener** ilə silinir.","**{ once: true }** → funksiya **yalnız bir dəfə** işləyir.","Yayılım 3 aşama: **capturing → target → bubbling**. Varsayılan: **bubbling** (hədəfdən **yuxarı**).","**capture: true** (və ya 3-cü parametr **true**) → üst öğe **əvvəl** tutur (\"Body\" sonra \"Buton\").","**event.stopPropagation()** → olayın üst öğelərə yayılmasını **dayandırır**."]}],"number":9,"title":"DOM və olay yönetimi","traps":["Bubbling yuxarıdan aşağı **deyil**, hədəfdən **yuxarı** qalxır (aşağı enən capturing-dir).","getElementById siyahı **qaytarmır**, **tək öğe** qaytarır.","innerHTML yalnız mətn **deyil**, HTML etiketlərini də işləyir.","querySelectorAll tək öğe **deyil**, **NodeList** qaytarır."]},{"blocks":[{"heading":"Bootstrap","points":["**Twitter** tərəfindən hazırlanmış, **açık kaynaklı CSS çerçevesi**; **mobil öncelikli**.","İlk çıxış **2011**, **Bootstrap 5** — **2021** (ən son). Əlavə yolu: **CDN** (jsDelivr, önbellek → sürət) və ya **yerli fayllar**.","**.container**: **sabit genişlik**, kənarlarda boşluq. **.container-fluid**: ekranın **tamamı**. Növlər: container, container-fluid, container-{breakpoint}.","Breakpoints: **xs <576px, sm ≥576px, md ≥768px** … lg, xl, xxl (**≥1400px**).","Düzen sistemi: **Breakpoints + Containers + Grid**. Grid: **12 sütun**, **.row** + **.col** (.col-6 = yarı, .col-md-6)."]},{"heading":"Bootstrap sınıfları","points":["Tipografi: **.h1–.h6**, **.text-center** (ortalar), **.text-primary** (tema rəngi).","Tablo: **.table**, **.table-striped** (zebra), **.table-hover** (fare üstündə), **.table-dark**, **.table-responsive** (kiçik ekranda kaydırma).","Bileşenlər: **.alert** (uğur: alert-success), **.btn**, **.form-control**, **.card** (resim + başlık + mətn kutusu).","Form doğrulama: <form>-a class **needs-validation** + **novalidate** özelliği. Açılır liste: **form-select**."]},{"heading":"jQuery","points":["JavaScript **kütüphanesi**: az kod, **çapraz tarayıcı uyumu**. Söz dizimi: **$(\"seçici\").aksiyon()**.","Seçicilər: **$(\"p\")** bütün <p>-lər, **$(\"#id\")** ID, **$(\".sinif\")** class.","Olaylar: **.click(), .hover(), .submit()**, .dblclick(), .keyup(), .change(), .focus(), .scroll().","Efektlər: show\/hide, **fadeIn** (yavaş görünür), fadeOut, slideDown\/Up, toggle, **.animate()**; süre ms və ya \"slow\"\/\"fast\".","DOM: **.text(), .html(), .attr(), .css()**, add\/remove\/toggleClass, **.append()** (sonuna əlavə), .prepend(), .remove().","AJAX (səhifə yenilənmədən): **.ajax(), .get(), .post(), .getJSON(), .load()**."]}],"number":10,"title":"Bootstrap və jQuery","traps":["**.click()** DOM manipülasyonu **deyil**, olaydır.",".container ekranı tam **örtmür**, tam örtən **.container-fluid**-dir.","Grid **20** deyil, **12** sütundur.","**Tables** düzen sisteminin bileşeni **deyil** (Breakpoints, Containers, Grid).","Bootstrap 5 **Internet Explorer**-i dəstəkləmir; Windows-da **Safari** yoxdur."]},{"blocks":[{"heading":"Hız optimizasyonu","points":["**Tasarım düzeyi**: kod, **görsel** (sıxışdırma, ölçü), içerik optimizasyonu.","**Geliştirme düzeyi**: **harici kaynak** (azalt, tək faylda birləşdir), **önbellekleme**, **eşzamansız yükleme**.","**Dağıtım düzeyi**: **yük dengeleme**, **CDN** (ən yaxın sunucudan), **sunucu** optimizasyonu.","**Lazy Loading**: görselləri gec yükləyib **yüklenme süresini azaldır**. **LCP** ideal: **2,5 saniyədən az**."]},{"heading":"SEO","points":["Məqsəd: alqoritmlərə uyğun quruluşla **organik trafiği artırmaq**.","**Sayfa içi**: başlıklar və **meta etiketlər**, **anahtar kelime** (təbii, təkrarsız), içerik yapısı.","**Sayfa dışı**: **geri bağlantılar** (backlink), **sosyal medya sinyalleri**, **marka otoritesi**.","**Teknik**: **URL yapısı və XML site haritası**, **mobil uyumluluk**, **site hızı və erişilebilirlik**."]},{"heading":"Güvenlik","points":["Başlıqlar: **Protokoller ve Standartlar**, **Politikalar ve Prensipler**, **Saldırılar ve Testler**.","Veri iletimi: **SSL\/TLS**. **Bütünlük**: verinin yetkisiz **dəyişdirilməməsi**.","Yaygın saldırılar: **XSS, SQL (injection), CSRF**. OWASP: yazılım güncellemeleri → **yazılım ve veri bütünlüğü hataları**."]}],"number":11,"title":"Performans, SEO, güvenlik","traps":["**Sosyal medya** teknik SEO **deyil**, sayfa dışı SEO-dur.","Geri bağlantılar sayfa içi **deyil**, sayfa dışıdır.","SERP \"yalnız reklam səhifəsi\" **deyil**.","CDN və yük dengeleme tasarım düzeyi **deyil**, **dağıtım** düzeyidir."]},{"blocks":[{"heading":"Əsaslar","points":["CMS: **kodlama bilgisi olmadan** içerik yaratmaq, düzənləmək, yayımlamaq; **çox istifadəçili** iş.","Tarix: masaüstü HTML düzenleyicilər (**CityDesk, MarsEdit**) → sunucu tabanlı sistemlər.","Bileşenlər: **düzenleme arayüzü, içerik deposu, yayınlama modülü, güvenlik ve erişim kontrolü**.","İçerik = **öz** (mətn, görsel, səs, video) + **metadata** (başlık, anahtar kelime, açıklama).","**CMS** → içerik üretimi və yayını; **DAM** → faylların **mərkəzi depolanması**."]},{"heading":"Üstünlük \/ çatışmazlıq","points":["Üstünlük: **teknik bilgi tələb etmir**, zaman qənaəti, işbirliyi, tema\/eklenti esnekliyi, SEO, maliyet verimliliği.","Açık kaynak üstünlüyü: **topluluk desteği ilə davamlı inkişaf**.","Çatışmazlıq: populyar CMS **güvenlik riski**, çox eklenti → **performans** problemi, bakım ehtiyacı, **vendor lock-in**.","**Tema** → sitenin **görsel tasarımı və düzəni**; **eklenti** → əlavə funksiya (SEO, güvenlik, e-ticaret)."]},{"heading":"Platformlar və gələcək","points":["**WordPress**: ən yaygın, **dinamik sayt və blog**. **Joomla**, **Drupal** (böyük, kurumsal, yüksək güvenlik) — **açık kaynak**.","**Craft CMS** (geliştiricilər), **DNN** (.NET), **Wix \/ Squarespace** (**bulut**, sürükle-bırak), **Shopify** (**e-ticaret**), **Moodle** (**LMS**, təhsil).","**Statik** sayt: sabit HTML\/CSS\/JS, sürətli, güvənli. **Dinamik**: veritabanı, içerik istifadəçiyə görə **dəyişir**.","Gələcək: **mobil uyumluluk və duyarlı tasarım** (PWA), güvenlik\/güncellemeler, açık kaynak; **Headless \/ API-First**."]}],"number":12,"title":"İçerik Yönetim Sistemleri (CMS)","traps":["Moodle e-ticaret **deyil**, **LMS**-dir; e-ticarət Shopify-dır.","Wix açık kaynak masaüstü **deyil**, **bulut tabanlı**dır.","DAM içerik yayınlamır, faylları **depolayır**.","Statik sayt veritabanından içerik **çəkmir**."]},{"blocks":[{"heading":"Rolu","points":["Ən böyük yenilik: **rutin, təkrarlanan işləri avtomatlaşdırıb** verimliliyi artırmaq.","Planlama: **persona** yaratmaq, **bir sayt üçün birdən çox konsept** təklif etmək.","Arayüz: **Figma AI, Galileo AI** mətn komutundan taslak; UX üçün **menyu yerləşimi, düymə ölçüsü, gezinme yolları** təklifi.","Kişiselleştirme: **tıklama\/gezinme davranışını analiz** edib xüsusi içerik\/məhsul təklif edir.","Erişilebilirlik: videolara **avtomatik altyazı**, görsəlləri\/mətni **seslendirmə**."]},{"heading":"Araçlar","points":["Kodlama: **GitHub Copilot, Codeium, Tabnine**. Tasarım: **Figma AI, Uizard, Galileo AI**.","Görsel: **MidJourney, Stable Diffusion, DALL·E**. Mətn: **ChatGPT, Jasper AI, Copy.ai**.","Səs\/video: **RunwayML, Pika Labs**. SEO: **SurferSEO, MarketMuse**.","VS Code eklentiləri: **Copilot**, Codeium, **Cline**, **Continue**; Microsoft-un **AI Toolkit**-i (Azure OpenAI, Hugging Face)."]},{"heading":"İki üsul və sınırlar","points":["**Tarayıcı tabanlı**: ChatGPT-dən **persona, hedefler, kullanıcı akışları**, sonra HTML\/CSS\/JS → VS Code-a yapışdır.","**VS Code + Copilot**: sohbet ekranında kod, **\"Insert into New File\"** (Yeni Dosyaya Ekle) ilə fayla.","Üstünlük: süreci sürətləndirir, **maliyeti və hata oranını azaldır**.","Sınır: **yaradıcılığı məhdudlaşdırma riski** və **içerik özgünlüğü**."]}],"number":13,"title":"Web tasarımında yapay zekâ","traps":["RunwayML kodlama aracı **deyil**, **video** aracıdır.","MidJourney\/DALL·E mətn yox, **görsel** üretir.","\"Kod içindəki güvenlik açıqlarını tapa bilməsi\" etik tartışma **deyil**.","Bütün kontrolü AI-a vermək tövsiyə **olunmur**."]},{"blocks":[{"heading":"Planlama və tasarım","points":["**İlk addım**: **ihtiyaç analizi ve planlama** (amac, hedef kitle, paydaş görüşləri; Notion, Trello, Google Docs).","**Site haritası**: **sayfalar və aralarındakı bağlantılar**, menyu düzəni.","**Kullanıcı akışı (user flow)**: girişdən hədəfə qədər addımlar (məs. axtar → sepet → ödəniş).","**Storyboard**: kullanıcı yolculuğunu **sahne sahne** görselləşdirir.","**Wireframe**: iskelet, **görsel detal olmadan** düzən; estetik yox, **işlevsellik**. **Mockup**: renk, tipografi, ikon, logo ilə **son görünüşə yaxın**.","Sıra: **Wireframe → Mockup → Prototip**. Prototip: yayımdan əvvəl **işləyən model**, **hataları tapmağı asanlaşdırır**."]},{"heading":"Geliştirme və test","points":["**Frontend**: HTML (iskelet), CSS (görsel), JS (etkileşim); **Bootstrap, Tailwind** — istifadəçi arayüzü, düymələr.","**Backend**: **veritabanı, kimlik doğrulama, yetkilendirme**; **Django** (Python), **Laravel** (PHP).","Testlər: **birim**, **entegrasyon**, **kullanılabilirlik**, **performans və güvenlik**."]},{"heading":"Yayına alma və bakım","points":["**Alan adı**: qısa, yadda qalan. **Hosting** → fayllar **FTP, Git, Docker** ilə.","**DNS** alan adını sunucuya yönləndirir, **SSL** güvenli bağlantı.","Yayın son **deyil**: güncelleme, güvenlik yamaları, **yedekleme**, **Google Analytics** ilə analiz."]}],"number":14,"title":"Yol haritası və yayına alma","traps":["**Tipografi testi** test növü **deyil**.","**Sayfa düzeni (layout)** backend **deyil**, frontend-dir.","Wireframe-də renk və tipografi **yoxdur**, onlar mockup-dadır.","**Mockminus** mock-up hazırlama mühiti **deyil**."]}]}};
